/* Tarjetas de repetición espaciada. Cada tarjeta es un concepto evaluable,
   con respuesta esperada, ejemplo y misconceptions para el feedback. */
window.FLASHCARDS = [
  /* ---------- Día 1 · Arquitectura ---------- */
  { id: 'c-kernel-distro', module: 'd1-arquitectura', topic: 'Linux', sub: 'Fundamentos', difficulty: 1,
    q: '¿Cuál es la diferencia entre Linux y una distribución como Ubuntu?',
    a: 'Linux es el kernel: administra CPU, memoria, discos y dispositivos. Una distribución empaqueta ese kernel con herramientas GNU, gestor de paquetes, configuración y soporte. Ubuntu, Debian y Rocky son distribuciones; Linux es el núcleo común.',
    example: 'uname -a muestra el kernel (Linux 6.1.0-18-amd64); cat /etc/os-release muestra la distro (Debian 12).',
    misconceptions: ['Decir que Ubuntu es un kernel', 'Creer que cada distro tiene un kernel distinto por definición'],
    related: ['c-fhs-etc', 'c-pid1'], tags: ['linux', 'fundamentos'] },
  { id: 'c-fhs-etc', module: 'd1-arquitectura', topic: 'Linux', sub: 'FHS', difficulty: 1,
    q: '¿Qué guarda /etc y por qué es importante en administración?',
    a: '/etc contiene la configuración del sistema y de los servicios en archivos de texto plano. Editarlos y recargar el servicio es la forma estándar de cambiar comportamiento; versionarlos permite auditar y revertir.',
    example: '/etc/nginx/nginx.conf, /etc/ssh/sshd_config, /etc/fstab, /etc/os-release.',
    misconceptions: ['Buscar configuración en /var', 'Editar y no recargar el servicio'],
    related: ['c-var', 'c-proc'], tags: ['linux', 'fhs'] },
  { id: 'c-var', module: 'd1-arquitectura', topic: 'Linux', sub: 'FHS', difficulty: 1,
    q: '¿Qué tipo de datos viven en /var y qué riesgo operativo tiene?',
    a: 'Datos variables que crecen: logs (/var/log), bases de datos (/var/lib), colas y contenido web (/var/www). Si una partición /var se llena, los servicios dejan de escribir y fallan; por eso suele monitorearse el uso de disco.',
    example: 'df -h /var && du -sh /var/* | sort -h | tail',
    misconceptions: ['Pensar que /var es solo logs', 'Ignorar el agotamiento de inodos (df -i)'],
    related: ['c-disco-lleno', 'c-logs'], tags: ['linux', 'fhs', 'disco'] },
  { id: 'c-proc', module: 'd1-arquitectura', topic: 'Linux', sub: 'FHS', difficulty: 2,
    q: '¿Qué es /proc y consume espacio en disco?',
    a: 'Es un pseudofilesystem creado por el kernel en memoria RAM. Expone estado de procesos y hardware (/proc/cpuinfo, /proc/meminfo, /proc/<PID>). No ocupa espacio en disco y su contenido es dinámico.',
    example: 'cat /proc/loadavg; cat /proc/meminfo | head',
    misconceptions: ['Creer que se puede respaldar /proc', 'Pensar que ocupa disco'],
    related: ['c-load'], tags: ['linux', 'fhs'] },
  { id: 'c-pid1', module: 'd1-arquitectura', topic: 'Linux', sub: 'Arranque', difficulty: 2,
    q: '¿Qué es PID 1 y por qué importa en contenedores?',
    a: 'PID 1 es el primer proceso del espacio de usuario; en sistemas modernos es systemd y es padre de todos los procesos. En un contenedor, el proceso principal debe quedarse en primer plano y manejar señales; si termina, el contenedor muere.',
    example: 'ps -p 1 -o comm=  →  systemd\nEn Docker: CMD ["node","server.js"] (foreground)',
    misconceptions: ['Usar systemd dentro de un contenedor sin init', 'Lanzar el proceso en background y que el contenedor salga'],
    related: ['c-kernel-distro', 'c-exit-codes'], tags: ['linux', 'arranque', 'docker'] },
  { id: 'c-journalctl', module: 'd1-arquitectura', topic: 'Linux', sub: 'Logs', difficulty: 2,
    q: '¿Cómo consultás los logs de un servicio con systemd?',
    a: 'journalctl -u nombre. Opciones útiles: -f para seguir en vivo, -n 100 para últimas líneas, --since "10 min ago" y -p err para errores. Los logs se leen sin paginador con --no-pager.',
    example: 'journalctl -u nginx --since "15 min ago" -p err --no-pager',
    misconceptions: ['Buscar siempre en /var/log aunque el servicio use journal', 'Olvidar que un servicio fallido registra la causa en el journal'],
    related: ['c-logs', 'c-systemd-enable'], tags: ['linux', 'logs', 'systemd'] },

  /* ---------- Día 1 · Permisos ---------- */
  { id: 'c-octal', module: 'd1-permisos', topic: 'Linux', sub: 'Permisos', difficulty: 2,
    q: '¿Qué significan los permisos 750 y 644?',
    a: '750 = rwx (7) para el dueño, r-x (5) para el grupo, --- (0) para otros. 644 = rw- (6) dueño, r-- (4) grupo, r-- (4) otros. Cada dígito es la suma de r=4, w=2, x=1.',
    example: 'chmod 750 script.sh  →  -rwxr-x---\nchmod 644 config.txt →  -rw-r--r--',
    misconceptions: ['Sumar mal los bits', 'Usar 777 como solución universal'],
    related: ['c-dir-perms', 'c-sgid'], tags: ['linux', 'permisos'] },
  { id: 'c-dir-perms', module: 'd1-permisos', topic: 'Linux', sub: 'Permisos', difficulty: 2,
    q: '¿Qué significa r, w y x en un directorio?',
    a: 'r permite listar nombres; w permite crear, borrar y renombrar entradas; x permite atravesar el directorio (cd) y acceder a los inodos. Sin x no se puede abrir un archivo aunque tenga permisos de lectura.',
    example: 'chmod 750 /srv/app  →  drwxr-x---\nls -ld /srv/app',
    misconceptions: ['Creer que x solo sirve para ejecutar', 'Pensar que r en directorio permite abrir archivos'],
    related: ['c-octal', 'c-acl'], tags: ['linux', 'permisos'] },
  { id: 'c-sgid', module: 'd1-permisos', topic: 'Linux', sub: 'Permisos especiales', difficulty: 3,
    q: '¿Para qué sirve SGID en un directorio y cómo se activa?',
    a: 'Hace que los archivos y subdirectorios nuevos hereden el grupo del directorio en vez del grupo primario del creador. Es la base de carpetas compartidas por equipo. Se activa con 2000 en octal (por ejemplo 2770) o chmod g+s.',
    example: 'chmod 2770 /srv/compras  →  drwxrws---',
    misconceptions: ['Confundir SGID con SUID', 'Pensar que SGID aplica solo a binarios'],
    related: ['c-suid', 'c-sticky'], tags: ['linux', 'permisos', 'sgid'] },
  { id: 'c-suid', module: 'd1-permisos', topic: 'Linux', sub: 'Permisos especiales', difficulty: 3,
    q: '¿Qué es SUID y qué riesgo tiene?',
    a: 'SUID (4000) hace que un binario se ejecute con los privilegios de su dueño, no del usuario que lo lanza. Ejemplo legítimo: /usr/bin/passwd escribe /etc/shadow como root. Riesgo: un binario SUID vulnerable o mal configurado permite escalar privilegios.',
    example: 'find / -perm -4000 -type f 2>/dev/null\nls -l /usr/bin/passwd  →  -rwsr-xr-x',
    misconceptions: ['No auditar binarios SUID en hardening', 'Creer que SUID afecta a scripts interpretados'],
    related: ['c-sgid', 'c-sudo'], tags: ['linux', 'seguridad', 'permisos'] },
  { id: 'c-sticky', module: 'd1-permisos', topic: 'Linux', sub: 'Permisos especiales', difficulty: 2,
    q: '¿Qué hace el sticky bit y dónde se usa normalmente?',
    a: 'En un directorio compartido permite que solo el dueño del archivo (o root) lo borre o renombre, aunque todos puedan escribir. Se usa en /tmp. En octal es 1000; se ve como t al final de los permisos.',
    example: 'ls -ld /tmp  →  drwxrwxrwt',
    misconceptions: ['Confundirlo con SGID', 'Creer que impide escribir en el directorio'],
    related: ['c-sgid', 'c-dir-perms'], tags: ['linux', 'permisos'] },
  { id: 'c-usermod-aG', module: 'd1-permisos', topic: 'Linux', sub: 'Usuarios', difficulty: 2,
    q: '¿Por qué usermod -G sin -a es peligroso?',
    a: 'Sin -a, -G reemplaza todos los grupos secundarios del usuario. Con -aG agrega el nuevo grupo conservando los anteriores. El error es frecuente y deja al usuario sin acceso a recursos que ya usaba.',
    example: 'usermod -aG docker ana\nid ana',
    misconceptions: ['Asumir que -G agrega por defecto', 'No verificar con id'],
    related: ['c-sudo', 'c-acl'], tags: ['linux', 'usuarios'] },
  { id: 'c-acl', module: 'd1-permisos', topic: 'Linux', sub: 'Permisos especiales', difficulty: 3,
    q: '¿Cuándo usás ACL en lugar de cambiar el grupo del archivo?',
    a: 'Cuando necesitás dar acceso puntual a un usuario o grupo sin alterar la pertenencia principal ni los permisos de todos los demás. setfacl -m agrega la regla y getfacl la audita.',
    example: 'setfacl -m u:carlos:r-x /srv/ventas\ngetfacl /srv/ventas',
    misconceptions: ['Meter al usuario en el grupo solo por una excepción', 'Olvidar que las ACL requieren soporte del filesystem'],
    related: ['c-sgid', 'c-dir-perms'], tags: ['linux', 'acl'] },
  { id: 'c-sudo', module: 'd1-permisos', topic: 'Linux', sub: 'Usuarios', difficulty: 2,
    q: '¿Cómo se aplica menor privilegio con sudo?',
    a: 'Otorgando comandos específicos y, si es posible, restringidos por usuario/host, en lugar de ALL=(ALL) NOPASSWD. Para servicios, correr con un usuario dedicado sin shell. sudo -l verifica qué puede ejecutar el usuario.',
    example: 'sudo -l\n# /etc/sudoers.d/deploy: deploy ALL=(root) /bin/systemctl restart miapp',
    misconceptions: ['Dar sudo total al usuario de deploy', 'Correr contenedores como root por comodidad'],
    related: ['c-suid', 'c-usermod-aG'], tags: ['linux', 'seguridad', 'sudo'] },

  /* ---------- Día 1 · Procesos ---------- */
  { id: 'c-proc-states', module: 'd1-procesos', topic: 'Linux', sub: 'Procesos', difficulty: 2,
    q: '¿Qué significan los estados R, S, D, T y Z de un proceso?',
    a: 'R ejecutando o listo; S esperando de forma interrumpible; D espera crítica de I/O que no responde a señales; T detenido; Z zombie, terminó pero el padre no recolectó su estado.',
    example: 'ps aux | awk \'{print $8}\' | sort | uniq -c',
    misconceptions: ['Creer que D se puede matar con -9', 'Confundir zombie con proceso que consume CPU'],
    related: ['c-sigterm', 'c-load'], tags: ['linux', 'procesos'] },
  { id: 'c-load', module: 'd1-procesos', topic: 'Linux', sub: 'Procesos', difficulty: 3,
    q: '¿Cómo se interpreta el load average?',
    a: 'Muestra procesos en ejecución o esperando recursos en 1, 5 y 15 minutos. Se compara con la cantidad de núcleos: en 4 núcleos, 4.00 es saturación plena y >4 indica cola. Incluye esperas de I/O, por eso un load alto con CPU baja sugiere disco.',
    example: 'nproc; uptime; cat /proc/loadavg',
    misconceptions: ['Leerlo sin conocer la cantidad de núcleos', 'Asumir que siempre es uso de CPU'],
    related: ['c-proc-states', 'c-top-mem'], tags: ['linux', 'rendimiento'] },
  { id: 'c-top-mem', module: 'd1-procesos', topic: 'Linux', sub: 'Procesos', difficulty: 2,
    q: '¿Qué diferencia hay entre VIRT, RES y SHR en top?',
    a: 'VIRT es la memoria virtual reservada (incluye mapeos y bibliotecas); RES es la RAM física realmente ocupada; SHR es la memoria compartida con otros procesos. Para dimensionar consumo real se mira RES.',
    example: 'top -o %MEM\nps aux --sort=-%mem | head',
    misconceptions: ['Sumar VIRT y concluir que falta RAM', 'Ignorar el OOM killer'],
    related: ['c-oom', 'c-load'], tags: ['linux', 'rendimiento', 'memoria'] },
  { id: 'c-sigterm', module: 'd1-procesos', topic: 'Linux', sub: 'Señales', difficulty: 2,
    q: '¿Cuál es la diferencia entre SIGTERM y SIGKILL?',
    a: 'SIGTERM (15) solicita un cierre ordenado: el proceso puede guardar estado y cerrar conexiones. SIGKILL (9) no puede capturarse ni ignorarse: el kernel lo termina de inmediato, con riesgo de corrupción de datos.',
    example: 'kill -15 2841   # esperar ~10s\nkill -9 2841    # último recurso',
    misconceptions: ['Usar -9 como primera opción', 'Esperar que SIGKILL ejecute handlers de limpieza'],
    related: ['c-exit-codes', 'c-proc-states'], tags: ['linux', 'señales'] },
  { id: 'c-oom', module: 'd1-procesos', topic: 'Linux', sub: 'Procesos', difficulty: 3,
    q: '¿Qué indica el exit code 137 en Docker o Kubernetes?',
    a: 'El proceso fue terminado por SIGKILL (128+9), normalmente por el OOM killer al superar el límite de memoria. En Kubernetes se reporta como OOMKilled y obliga a revisar limits, leaks o carga.',
    example: 'docker inspect web --format "{{.State.ExitCode}}"\nkubectl describe pod api | grep -A3 "Last State"',
    misconceptions: ['Buscar un error de aplicación cuando fue el kernel', 'Subir el límite sin analizar la causa'],
    related: ['c-top-mem', 'c-k8s-limits'], tags: ['linux', 'docker', 'k8s', 'memoria'] },
  { id: 'c-systemd-enable', module: 'd1-procesos', topic: 'Linux', sub: 'Servicios', difficulty: 2,
    q: '¿Qué diferencia hay entre systemctl start y systemctl enable?',
    a: 'start inicia el servicio ahora; enable lo configura para arrancar con el sistema creando los symlinks de la unidad. enable --now hace ambas cosas. status muestra estado actual y enabled/disabled.',
    example: 'systemctl enable --now nginx\nsystemctl is-enabled nginx; systemctl is-active nginx',
    misconceptions: ['Creer que start persiste tras un reinicio', 'Olvidar recargar tras cambiar configuración'],
    related: ['c-journalctl', 'c-pid1'], tags: ['linux', 'systemd'] },
  { id: 'c-nohup', module: 'd1-procesos', topic: 'Linux', sub: 'Servicios', difficulty: 2,
    q: '¿Para qué sirve nohup y qué problema resuelve?',
    a: 'Protege un proceso de SIGHUP al cerrar la terminal o la sesión SSH. Se usa con & para dejarlo en segundo plano; la salida se redirige a nohup.out salvo que se especifique otra.',
    example: 'nohup ./backup.sh > backup.log 2>&1 &',
    misconceptions: ['Creer que & alcanza al cerrar SSH', 'Perder stdout por no redirigir'],
    related: ['c-sigterm', 'c-systemd-enable'], tags: ['linux', 'procesos', 'ssh'] },
  { id: 'c-ss', module: 'd1-procesos', topic: 'Linux', sub: 'Red', difficulty: 2,
    q: '¿Cómo verificás qué proceso escucha en un puerto?',
    a: 'Con ss -tulpn: muestra sockets TCP/UDP, puertos en escucha y el proceso dueño con su PID. Si el puerto está tomado, el servicio nuevo no arranca y el log lo indica.',
    example: 'ss -tulpn | grep :80',
    misconceptions: ['Usar netstat -an sin -p', 'No relacionar puerto ocupado con el fallo del servicio'],
    related: ['c-ports', 'c-502'], tags: ['linux', 'redes'] },

  /* ---------- Día 1 · Texto ---------- */
  { id: 'c-redirect', module: 'd1-texto', topic: 'Linux', sub: 'Shell', difficulty: 2,
    q: '¿Cuál es la diferencia entre > y >>?',
    a: '> sobrescribe el archivo destino (pierde el contenido previo); >> agrega al final. Para logs se usa >>. Con > archivo 2>&1 se redirigen stdout y stderr al mismo archivo.',
    example: 'echo "inicio" >> /var/log/deploy.log\n./script.sh > salida.log 2>&1',
    misconceptions: ['Usar > en un log acumulativo', 'Olvidar redirigir stderr'],
    related: ['c-fd', 'c-tee'], tags: ['linux', 'shell'] },
  { id: 'c-fd', module: 'd1-texto', topic: 'Linux', sub: 'Shell', difficulty: 2,
    q: '¿Qué son stdin, stdout y stderr?',
    a: 'Los tres descriptores estándar de todo proceso: 0 entrada, 1 salida normal y 2 errores. Redirigir 2> archivo guarda solo errores; 2>&1 los une a stdout.',
    example: 'comando 2> errores.log\ncomando > todo.log 2>&1',
    misconceptions: ['Creer que los errores van a stdout', 'Pensar que 2>&1 funciona sin orden correcto'],
    related: ['c-redirect', 'c-tee'], tags: ['linux', 'shell'] },
  { id: 'c-tee', module: 'd1-texto', topic: 'Linux', sub: 'Shell', difficulty: 1,
    q: '¿Para qué sirve tee en un pipeline?',
    a: 'Duplica stdout: lo muestra en pantalla y lo escribe en un archivo a la vez. Se usa para guardar evidencia de un comando que también querés ver.',
    example: 'comando | tee salida.log',
    misconceptions: ['Confundirlo con redirección simple', 'Olvidar -a para no sobrescribir'],
    related: ['c-redirect', 'c-fd'], tags: ['linux', 'shell'] },
  { id: 'c-grep-v', module: 'd1-texto', topic: 'Linux', sub: 'Texto', difficulty: 2,
    q: '¿Qué hace grep -v y cuándo es útil?',
    a: 'Invierte el filtro: muestra las líneas que NO coinciden. Es útil para limpiar configuración de comentarios y líneas vacías: grep -v "^#" archivo | grep -v "^$".',
    example: 'grep -v "^#" /etc/ssh/sshd_config | grep -v "^$"',
    misconceptions: ['Pensar que -v es verbose (eso es -V en otros comandos)', 'Encadenar mal los filtros'],
    related: ['c-awk', 'c-find'], tags: ['linux', 'texto'] },
  { id: 'c-awk', module: 'd1-texto', topic: 'Linux', sub: 'Texto', difficulty: 3,
    q: '¿Cómo extraés la primera columna de un archivo con awk?',
    a: 'awk \'{print $1}\' archivo. Cada campo se separa por espacios por defecto; $1 es la primera columna y $NF la última. Combinado con sort y uniq -c cuenta ocurrencias.',
    example: 'awk \'{print $1}\' access.log | sort | uniq -c | sort -rn | head',
    misconceptions: ['Confundir $1 con la primera línea', 'Olvidar -F para separadores distintos de espacio'],
    related: ['c-grep-v', 'c-find'], tags: ['linux', 'texto', 'logs'] },
  { id: 'c-find', module: 'd1-texto', topic: 'Linux', sub: 'Texto', difficulty: 2,
    q: '¿Cómo buscás archivos por tamaño y ejecutás una acción?',
    a: 'find ruta -type f -size +100M -exec comando {} \\;. -exec aplica el comando a cada resultado; {} representa el archivo y \\; cierra la expresión. También admite -mtime, -name y -perm.',
    example: 'find /var/log -type f -size +100M -exec ls -lh {} \\;',
    misconceptions: ['Usar find sin -type y recorrer todo', 'Olvidar las comillas en -name "*.log"'],
    related: ['c-grep-v', 'c-awk'], tags: ['linux', 'texto'] },
  { id: 'c-vim', module: 'd1-texto', topic: 'Linux', sub: 'Editores', difficulty: 1,
    q: '¿Cómo guardás y salís de vim, y cómo salís sin guardar?',
    a: 'En modo comando, :wq guarda y sale; :q! sale descartando cambios. i entra a inserción y Esc vuelve a modo normal. Buscar es /patrón y reemplazar todo :%s/viejo/nuevo/g.',
    example: ':wq\n:q!\n:%s/listen 80/listen 8080/g',
    misconceptions: ['Quedarse en modo inserción sin poder salir', 'Usar :q con cambios pendientes y frustrarse'],
    related: ['c-fd', 'c-redirect'], tags: ['linux', 'vim'] },

  /* ---------- Día 1 · Redes ---------- */
  { id: 'c-dns', module: 'd1-redes', topic: 'Redes', sub: 'DNS', difficulty: 2,
    q: '¿Qué hace DNS y cómo lo diagnosticás?',
    a: 'Traduce nombres a direcciones IP mediante registros (A, AAAA, CNAME, MX, TXT). Se diagnostica con dig +short nombre o nslookup, probando también un resolver público con dig @8.8.8.8. Un fallo DNS da "no such host" o "name not resolved", no un 502.',
    example: 'dig +short api.empresa.com\ndig @8.8.8.8 api.empresa.com',
    misconceptions: ['Culpar a la app por un error de resolución', 'No revisar /etc/resolv.conf en contenedores'],
    related: ['c-502', 'c-ports'], tags: ['redes', 'dns'] },
  { id: 'c-502', module: 'd1-redes', topic: 'Redes', sub: 'HTTP', difficulty: 3,
    q: '¿Qué diferencia hay entre 502 y 504?',
    a: '502 Bad Gateway: el proxy no pudo obtener una respuesta válida del upstream (app caída, puerto equivocado, nombre no resuelve). 504 Gateway Timeout: el upstream respondió demasiado tarde; el proxy cortó por timeout.',
    example: 'curl -I https://app\n# HTTP/2 502 → revisar upstream con ss y logs\n# HTTP/2 504 → revisar latencia y timeouts del proxy',
    misconceptions: ['Decir que 502 es error del cliente', 'Subir el timeout sin investigar la causa'],
    related: ['c-dns', 'c-ports'], tags: ['redes', 'http', 'troubleshooting'] },
  { id: 'c-ports', module: 'd1-redes', topic: 'Redes', sub: 'Puertos', difficulty: 2,
    q: '¿Qué significa que un servicio escuche en 127.0.0.1 en lugar de 0.0.0.0?',
    a: '127.0.0.1 solo acepta conexiones locales; desde fuera del contenedor o del host no es alcanzable. 0.0.0.0 escucha en todas las interfaces. En contenedores y Kubernetes esto es una causa habitual de "no conecta".',
    example: 'ss -tulpn | grep :8080\napp.listen(8080, "0.0.0.0")',
    misconceptions: ['Publicar el puerto y no entender por qué no responde', 'Confundir puerto host con puerto contenedor'],
    related: ['c-dns', 'c-compose-port'], tags: ['redes', 'docker'] },
  { id: 'c-tcp-udp', module: 'd1-redes', topic: 'Redes', sub: 'Protocolos', difficulty: 2,
    q: '¿Por qué DNS usa UDP por defecto y HTTP usa TCP?',
    a: 'DNS prioriza latencia y consultas pequeñas, por eso usa UDP con reintentos (y TCP para respuestas grandes o transferencias de zona). HTTP necesita entrega ordenada, control de flujo y retransmisión, que TCP provee.',
    example: 'dig +notcp example.com\ndig +tcp example.com',
    misconceptions: ['Decir que DNS solo usa UDP', 'Ignorar que QUIC/HTTP3 usa UDP'],
    related: ['c-dns', 'c-502'], tags: ['redes', 'protocolos'] },
  { id: 'c-ssh', module: 'd1-redes', topic: 'Redes', sub: 'SSH', difficulty: 2,
    q: '¿Cómo funciona la autenticación SSH por clave?',
    a: 'Se genera un par: la clave privada queda en el cliente y la pública se copia a ~/.ssh/authorized_keys del servidor. El servidor plantea un desafío que solo puede resolver quien posee la privada. Nunca se transmite la privada.',
    example: 'ssh-keygen -t ed25519\nssh-copy-id ana@servidor\nssh ana@servidor',
    misconceptions: ['Copiar la clave privada al servidor', 'Dejar PasswordAuthentication activo sin necesidad'],
    related: ['c-ports', 'c-sudo'], tags: ['redes', 'ssh', 'seguridad'] },
  { id: 'c-subnet', module: 'd1-redes', topic: 'Redes', sub: 'Cloud', difficulty: 3,
    q: '¿Qué diferencia hay entre una subnet pública y una privada?',
    a: 'La pública tiene ruta al Internet Gateway y puede recibir tráfico externo (balanceadores, bastión). La privada no tiene ruta directa a internet: sale por NAT Gateway y aloja apps y bases de datos.',
    example: 'VPC 10.0.0.0/16 → 10.0.1.0/24 pública (ALB), 10.0.2.0/24 privada (app + RDS)',
    misconceptions: ['Poner la base de datos en pública "para que funcione"', 'Confundir subnet con security group'],
    related: ['c-sg-nacl', 'c-iam-role'], tags: ['redes', 'cloud'] },
  { id: 'c-sg-nacl', module: 'd1-redes', topic: 'Redes', sub: 'Cloud', difficulty: 3,
    q: '¿Diferencia entre Security Group y NACL?',
    a: 'Security Group es un firewall stateful a nivel de instancia: solo reglas allow y el tráfico de respuesta se permite automáticamente. NACL es stateless a nivel de subnet: permite y deniega, y requiere reglas de entrada y salida explícitas.',
    example: 'SG: inbound 443 desde 0.0.0.0/0, outbound all\nNACL: reglas numeradas en ambos sentidos',
    misconceptions: ['Olvidar la regla de salida en NACL', 'Creer que el SG deniega explícitamente (solo permite)'],
    related: ['c-subnet', 'c-iam-role'], tags: ['redes', 'cloud', 'seguridad'] },
  { id: 'c-iam-role', module: 'd1-redes', topic: 'Redes', sub: 'Cloud', difficulty: 2,
    q: '¿Por qué usar un rol IAM en lugar de claves de acceso en una instancia?',
    a: 'El rol entrega credenciales temporales rotadas automáticamente por el proveedor y evita secretos estáticos en disco o en el código. Las claves de acceso de larga duración son un riesgo alto si se filtran.',
    example: 'aws sts get-caller-identity  # muestra el rol asumido, sin claves en la instancia',
    misconceptions: ['Guardar Access Key en variables de entorno de la VM', 'Dar AdministratorAccess al rol de la app'],
    related: ['c-sg-nacl', 'c-secret-leak'], tags: ['cloud', 'iam', 'seguridad'] },

  /* ---------- Día 1 · Git ---------- */
  { id: 'c-git-areas', module: 'd1-git', topic: 'Git', sub: 'Fundamentos', difficulty: 2,
    q: '¿Cuáles son las tres áreas de Git?',
    a: 'Working tree (archivos tal como están), index o staging (lo preparado con git add) y repositorio (commits). git status muestra el estado de cada área y git diff compara working tree contra index.',
    example: 'git status\ngit diff        # working tree vs index\ngit diff --staged',
    misconceptions: ['Creer que git add guarda el cambio', 'Confundir commit con push'],
    related: ['c-merge-rebase', 'c-revert'], tags: ['git'] },
  { id: 'c-merge-rebase', module: 'd1-git', topic: 'Git', sub: 'Ramas', difficulty: 3,
    q: '¿Cuándo usar merge y cuándo rebase?',
    a: 'merge integra preservando la historia real y crea un commit de unión; es seguro para ramas compartidas. rebase reescribe los commits sobre otra base para lograr historia lineal; solo en ramas locales o privadas, nunca en main ni en ramas ya publicadas.',
    example: 'git switch feature\n# actualizar con main:\ngit rebase main\ngit switch main && git merge feature',
    misconceptions: ['Hacer rebase de main', 'Rebasar una rama con revisión abierta y forzar push'],
    related: ['c-conflict', 'c-git-areas'], tags: ['git', 'ramas'] },
  { id: 'c-conflict', module: 'd1-git', topic: 'Git', sub: 'Ramas', difficulty: 2,
    q: '¿Cómo se resuelve un conflicto de merge?',
    a: 'Git marca el archivo con <<<<<<<, ======= y >>>>>>>. Se edita dejando el contenido final, se eliminan los marcadores, se hace git add del archivo y se completa con git commit. Si algo sale mal, git merge --abort vuelve al estado previo.',
    example: 'git merge feature\n# editar archivo\ngit add archivo\ngit commit\n# o: git merge --abort',
    misconceptions: ['Dejar marcadores en el archivo', 'Resolver sin releer ambos cambios'],
    related: ['c-merge-rebase', 'c-git-areas'], tags: ['git'] },
  { id: 'c-revert', module: 'd1-git', topic: 'Git', sub: 'Ramas', difficulty: 3,
    q: '¿Diferencia entre git revert y git reset?',
    a: 'revert crea un commit nuevo que deshace otro, sin reescribir historia: es seguro en ramas públicas y en producción. reset mueve la rama y puede borrar trabajo local (--hard); solo para commits no publicados.',
    example: 'git revert a1b2c3d\ngit reset --soft HEAD~1   # deshacer commit local conservando cambios',
    misconceptions: ['Usar reset --hard en main compartido', 'Creer que revert borra el commit original'],
    related: ['c-merge-rebase', 'c-git-areas'], tags: ['git', 'produccion'] },
  { id: 'c-git-secret', module: 'd1-git', topic: 'Git', sub: 'Seguridad', difficulty: 3,
    q: '¿Qué hacés si commiteaste una credencial?',
    a: 'Primero se rota o revoca la credencial: ya se considera comprometida. Después se elimina de la historia con git filter-repo (o BFG), se fuerza la actualización del remoto coordinando al equipo y se agrega detección de secretos en pre-commit y CI.',
    example: 'gitleaks detect --source . -v\n# rotar en el proveedor ANTES de reescribir historia',
    misconceptions: ['Solo borrar el archivo en un commit nuevo', 'Reescribir historia sin rotar la credencial'],
    related: ['c-iam-role', 'c-secrets'], tags: ['git', 'seguridad'] },
  { id: 'c-gitignore', module: 'd1-git', topic: 'Git', sub: 'Fundamentos', difficulty: 1,
    q: '¿Qué debería incluir un .gitignore en un proyecto con Docker?',
    a: 'node_modules, .env y archivos de secretos, dist/build, logs, .terraform y terraform.tfstate, y archivos locales del editor. Evita subir peso, secretos y estado generado.',
    example: '.gitignore: node_modules/ .env dist/ *.log .terraform/ *.tfstate',
    misconceptions: ['Commitear tfstate', 'Subir .env "porque el equipo lo necesita"'],
    related: ['c-tfstate', 'c-secrets'], tags: ['git', 'terraform'] },

  /* ---------- Día 2 · Contenedores ---------- */
  { id: 'c-vm-container', module: 'd2-contenedores', topic: 'Docker', sub: 'Fundamentos', difficulty: 2,
    q: '¿En qué se diferencia un contenedor de una máquina virtual?',
    a: 'La VM virtualiza hardware y corre un kernel propio completo. El contenedor es un proceso del host aislado con namespaces y limitado con cgroups: comparte el kernel, arranca en milisegundos y no reserva RAM de un SO completo.',
    example: 'docker run -d nginx:1.27  → proceso aislado, sin boot de SO',
    misconceptions: ['Decir que el contenedor es una VM liviana', 'Creer que el contenedor tiene su propio kernel'],
    related: ['c-namespaces', 'c-cgroups'], tags: ['docker', 'fundamentos'] },
  { id: 'c-namespaces', module: 'd2-contenedores', topic: 'Docker', sub: 'Fundamentos', difficulty: 3,
    q: '¿Qué aíslan los namespaces?',
    a: 'La visibilidad de recursos: PID (procesos), NET (interfaces y puertos), MNT (montajes), UTS (hostname), IPC y USER (mapeo de usuarios). Hacen que el contenedor crea que es el único en el sistema, aunque comparte kernel.',
    example: 'unshare --pid --fork --mount-proc bash   # aislar PID en un shell',
    misconceptions: ['Confundir aislamiento con seguridad absoluta', 'Creer que namespaces limitan CPU'],
    related: ['c-cgroups', 'c-vm-container'], tags: ['docker', 'linux'] },
  { id: 'c-cgroups', module: 'd2-contenedores', topic: 'Docker', sub: 'Fundamentos', difficulty: 3,
    q: '¿Qué hacen los cgroups y qué pasa si no los configurás?',
    a: 'Limitan y miden CPU, memoria, I/O y PIDs por grupo de procesos. Sin límites, un contenedor puede consumir todos los recursos del host y afectar a los demás. En Docker se aplican con --memory y --cpus; en Kubernetes con requests y limits.',
    example: 'docker run -d --memory=512m --cpus=1 nginx\ndocker stats --no-stream',
    misconceptions: ['Creer que el contenedor ya tiene límites por defecto', 'Poner limits sin requests en Kubernetes'],
    related: ['c-namespaces', 'c-k8s-limits'], tags: ['docker', 'linux', 'k8s'] },
  { id: 'c-exit-codes', module: 'd2-contenedores', topic: 'Docker', sub: 'Operación', difficulty: 2,
    q: '¿Qué significan los exit codes 0, 1, 137 y 143 en un contenedor?',
    a: '0 éxito; 1 error de la aplicación; 137 terminado por SIGKILL (128+9), típicamente OOMKilled; 143 terminado por SIGTERM (128+15), cierre ordenado. El código orienta el diagnóstico antes de leer logs.',
    example: 'docker inspect web --format "{{.State.ExitCode}} {{.State.OOMKilled}}"',
    misconceptions: ['Ignorar el código de salida', 'Asumir error de app ante un 137'],
    related: ['c-oom', 'c-sigterm'], tags: ['docker', 'troubleshooting'] },
  { id: 'c-capa', module: 'd2-contenedores', topic: 'Docker', sub: 'Imágenes', difficulty: 2,
    q: '¿Qué pasa con los datos escritos dentro de un contenedor?',
    a: 'Se escriben en una capa superior efímera sobre las capas de solo lectura de la imagen. Al eliminar el contenedor se pierden, salvo que estén en un volumen o bind mount.',
    example: 'docker run -d -v pgdata:/var/lib/postgresql/data postgres:16-alpine',
    misconceptions: ['Guardar una base de datos sin volumen', 'Hacer commit de un contenedor para persistir datos'],
    related: ['c-volume'], tags: ['docker', 'persistencia'] },
  { id: 'c-docker-logs', module: 'd2-contenedores', topic: 'Docker', sub: 'Operación', difficulty: 2,
    q: '¿De dónde salen los logs que muestra docker logs?',
    a: 'De stdout y stderr del proceso principal. Si la app escribe en un archivo interno o usa syslog, docker logs no muestra nada: hay que leer el archivo con exec o redirigir la salida a stdout.',
    example: 'docker logs --tail 100 -f api',
    misconceptions: ['Buscar logs de archivo con docker logs', 'No loguear a stdout en contenedores'],
    related: ['c-journalctl', 'c-k8s-logs'], tags: ['docker', 'logs'] },

  /* ---------- Día 2 · Imágenes ---------- */
  { id: 'c-cache', module: 'd2-imagenes', topic: 'Docker', sub: 'Dockerfile', difficulty: 3,
    q: '¿Cómo se aprovecha la cache de capas en un Dockerfile?',
    a: 'Cada instrucción genera una capa cacheada; si cambia, se invalida esa capa y todas las siguientes. Se copian primero los archivos que cambian menos (package.json y lockfile), se instalan dependencias y recién después se copia el código.',
    example: 'COPY package*.json ./\nRUN npm ci\nCOPY . .',
    misconceptions: ['Copiar todo antes de npm install', 'Usar latest y romper la cache/reproducibilidad'],
    related: ['c-multistage', 'c-npm-ci'], tags: ['docker', 'dockerfile'] },
  { id: 'c-npm-ci', module: 'd2-imagenes', topic: 'Docker', sub: 'Dockerfile', difficulty: 2,
    q: '¿Por qué usar npm ci en lugar de npm install en un build?',
    a: 'npm ci instala exactamente lo que dice el lockfile, borra node_modules y falla si hay desajuste: es reproducible y más rápido en CI. npm install puede actualizar versiones y generar builds distintos.',
    example: 'RUN npm ci --omit=dev',
    misconceptions: ['Usar npm install en pipelines', 'No commitear el lockfile'],
    related: ['c-cache', 'c-multistage'], tags: ['docker', 'node', 'ci'] },
  { id: 'c-multistage', module: 'd2-imagenes', topic: 'Docker', sub: 'Dockerfile', difficulty: 3,
    q: '¿Qué ventaja da un multi-stage build?',
    a: 'Permite compilar en una etapa con todo el toolchain y copiar solo el artefacto a una etapa final mínima. Reduce tamaño, superficie de ataque y tiempo de descarga del deploy.',
    example: 'FROM node:20 AS build\nWORKDIR /app\nCOPY . .\nRUN npm ci && npm run build\nFROM nginx:1.27-alpine\nCOPY --from=build /app/dist /usr/share/nginx/html',
    misconceptions: ['Copiar node_modules del build a runtime', 'Creer que multi-stage es solo para Java'],
    related: ['c-cache', 'c-user'], tags: ['docker', 'dockerfile'] },
  { id: 'c-user', module: 'd2-imagenes', topic: 'Docker', sub: 'Seguridad', difficulty: 2,
    q: '¿Cómo corrés un contenedor sin privilegios de root?',
    a: 'Creando o usando un usuario en la imagen con USER y asegurando que los archivos necesarios le pertenezcan. En runtime se puede reforzar con --user, --read-only y --cap-drop ALL.',
    example: 'USER node\ndocker run --user 1000:1000 --read-only miapp:1.0',
    misconceptions: ['Dejar USER root implícito', 'Cambiar USER y romper permisos de escritura sin analizar'],
    related: ['c-multistage', 'c-secrets'], tags: ['docker', 'seguridad'] },
  { id: 'c-entrypoint', module: 'd2-imagenes', topic: 'Docker', sub: 'Dockerfile', difficulty: 2,
    q: '¿Diferencia entre ENTRYPOINT y CMD?',
    a: 'ENTRYPOINT define el ejecutable fijo del contenedor; CMD define argumentos por defecto que pueden reemplazarse al hacer docker run. Juntos permiten una imagen con comportamiento fijo y parámetros flexibles.',
    example: 'ENTRYPOINT ["node", "server.js"]\nCMD ["--port", "3000"]',
    misconceptions: ['Usar solo CMD y esperar un ejecutable fijo', 'Sobrescribir ENTRYPOINT sin querer al pasar argumentos'],
    related: ['c-cache', 'c-user'], tags: ['docker', 'dockerfile'] },
  { id: 'c-dockerignore', module: 'd2-imagenes', topic: 'Docker', sub: 'Dockerfile', difficulty: 1,
    q: '¿Qué evita .dockerignore y por qué importa?',
    a: 'Evita enviar al contexto de build archivos innecesarios o sensibles: node_modules, .git, .env, dist y logs. Reduce el tiempo de build y el riesgo de filtrar secretos, además de invalidar cache menos veces.',
    example: '.dockerignore: node_modules .git .env *.log',
    misconceptions: ['Confundirlo con .gitignore', 'Copiar .env dentro de la imagen'],
    related: ['c-secrets', 'c-cache'], tags: ['docker', 'seguridad'] },

  /* ---------- Día 2 · Compose ---------- */
  { id: 'c-volume', module: 'd2-compose', topic: 'Docker', sub: 'Persistencia', difficulty: 2,
    q: '¿Cuándo usar volumen nombrado y cuándo bind mount?',
    a: 'Volumen nombrado para datos persistentes administrados por Docker (bases de datos, uploads): sobrevive a recrear contenedores y funciona mejor en otros sistemas. Bind mount para desarrollo (código en vivo) o para inyectar un archivo de configuración desde el host.',
    example: 'volumes: [pgdata:/var/lib/postgresql/data]\n# bind: ./nginx.conf:/etc/nginx/nginx.conf:ro',
    misconceptions: ['Usar bind mount para una base en producción', 'Usar ruta relativa sin entender desde dónde se resuelve'],
    related: ['c-capa', 'c-compose-dns'], tags: ['docker', 'compose'] },
  { id: 'c-compose-dns', module: 'd2-compose', topic: 'Docker', sub: 'Compose', difficulty: 2,
    q: '¿Cómo se conectan dos servicios en Docker Compose?',
    a: 'Por el nombre del servicio en la red del proyecto: la app usa db:5432, no localhost. Docker resuelve el nombre a la IP del contenedor. localhost dentro del contenedor apunta al propio contenedor.',
    example: 'environment:\n  DB_HOST: db\n  DB_PORT: 5432',
    misconceptions: ['Usar localhost entre contenedores', 'Publicar la base y conectar por IP del host'],
    related: ['c-compose-health', 'c-ports'], tags: ['docker', 'compose', 'redes'] },
  { id: 'c-compose-health', module: 'd2-compose', topic: 'Docker', sub: 'Compose', difficulty: 3,
    q: '¿Qué problema resuelve depends_on con condition service_healthy?',
    a: 'depends_on simple solo espera que el contenedor arranque, no que el servicio esté listo. Con condition service_healthy y un healthcheck, la app espera a que la dependencia responda, evitando fallos de conexión al inicio.',
    example: 'depends_on:\n  db:\n    condition: service_healthy\nhealthcheck:\n  test: ["CMD-SHELL", "pg_isready -U postgres"]',
    misconceptions: ['Creer que depends_on espera la disponibilidad', 'No definir healthcheck'],
    related: ['c-compose-dns', 'c-probes'], tags: ['docker', 'compose'] },
  { id: 'c-compose-down', module: 'd2-compose', topic: 'Docker', sub: 'Compose', difficulty: 1,
    q: '¿Qué hace docker compose down -v y cuándo es peligroso?',
    a: 'Baja los contenedores y elimina además los volúmenes nombrados del proyecto. Es útil para empezar de cero en desarrollo, pero destructivo si hay datos que querés conservar. down sin -v conserva los volúmenes.',
    example: 'docker compose down\ndocker compose down -v   # ¡borra datos!',
    misconceptions: ['Usar -v en staging/producción', 'Asumir que los datos están en la imagen'],
    related: ['c-volume', 'c-capa'], tags: ['docker', 'compose'] },
  { id: 'c-compose-port', module: 'd2-compose', topic: 'Docker', sub: 'Compose', difficulty: 2,
    q: '¿Qué significa ports "8080:80" y cuándo no hace falta publicar?',
    a: 'Mapea el puerto 8080 del host al 80 del contenedor. Solo hace falta para acceder desde fuera de la red Docker; entre servicios se usa el puerto interno. Exponer de más amplía la superficie de ataque.',
    example: 'ports: ["8080:80"]\n# entre servicios: http://web:80',
    misconceptions: ['Invertir host y contenedor', 'Publicar la base de datos innecesariamente'],
    related: ['c-compose-dns', 'c-ports'], tags: ['docker', 'compose'] },

  /* ---------- Día 2 · CI/CD ---------- */
  { id: 'c-cicd-defs', module: 'd2-cicd', topic: 'CI/CD', sub: 'Fundamentos', difficulty: 2,
    q: '¿Diferencia entre CI, Continuous Delivery y Continuous Deployment?',
    a: 'CI integra cada cambio con build y tests automáticos. Delivery deja todo cambio listo para desplegar con aprobación manual. Deployment despliega a producción automáticamente si pasan las validaciones.',
    example: 'CI: push → test. Delivery: test → listo + botón. Deployment: test → prod automático.',
    misconceptions: ['Usar CI y CD como sinónimos', 'Llamar CD a tener solo un script de build'],
    related: ['c-gate', 'c-pipeline'], tags: ['cicd'] },
  { id: 'c-pipeline', module: 'd2-cicd', topic: 'CI/CD', sub: 'Pipelines', difficulty: 2,
    q: '¿Qué etapas mínimas debería tener un pipeline confiable?',
    a: 'Checkout limpio, build con cache, tests unitarios y de integración, análisis de seguridad, empaquetado de artefacto versionado, deploy a staging, verificación (smoke tests) y deploy a producción con gate. Rollback siempre disponible.',
    example: 'push → lint → test → build image → scan → deploy staging → smoke → aprobar → prod',
    misconceptions: ['Deploy antes de testear', 'Reconstruir la imagen por ambiente'],
    related: ['c-artifact', 'c-gate'], tags: ['cicd'] },
  { id: 'c-artifact', module: 'd2-cicd', topic: 'CI/CD', sub: 'Pipelines', difficulty: 3,
    q: '¿Por qué se construye el artefacto una sola vez y se promueve?',
    a: 'Porque garantiza que lo que se probó es exactamente lo que se despliega. Reconstruir en cada ambiente introduce diferencias (dependencias, tags, cache) y rompe la trazabilidad. Se promueve la misma imagen por digest.',
    example: 'docker build -t app:${SHA} . && push\ndeploy staging: app:${SHA}\ndeploy prod: app:${SHA}',
    misconceptions: ['Rebuild en producción', 'Desplegar latest'],
    related: ['c-digest', 'c-cicd-defs'], tags: ['cicd', 'docker'] },
  { id: 'c-gate', module: 'd2-cicd', topic: 'CI/CD', sub: 'Pipelines', difficulty: 2,
    q: '¿Qué es un quality gate en un pipeline?',
    a: 'Una condición que bloquea el avance si no se cumple: tests verdes, cobertura mínima, sin vulnerabilidades críticas, aprobación manual para producción. Sin gates, el pipeline no protege nada.',
    example: 'if: always() + job de deploy con environment: production (requiere aprobación)',
    misconceptions: ['Permitir bypass permanente', 'Gate que nunca puede pasar y se ignora'],
    related: ['c-cicd-defs', 'c-sev-gate'], tags: ['cicd', 'calidad'] },
  { id: 'c-rollback', module: 'd2-cicd', topic: 'CI/CD', sub: 'Operación', difficulty: 2,
    q: '¿Cómo se diseña un rollback confiable?',
    a: 'Artefactos versionados e inmutables, infraestructura reproducible y un comando o botón para volver a la versión anterior (imagen previa, kubectl rollout undo o revert del commit). Practicado antes del incidente.',
    example: 'kubectl rollout undo deployment/api\ndocker pull app:1.3.9 && docker compose up -d',
    misconceptions: ['Rollback manual reconstruyendo desde Git', 'No probar nunca el rollback'],
    related: ['c-artifact', 'c-deploy-strategies'], tags: ['cicd', 'produccion'] },
  { id: 'c-deploy-strategies', module: 'd2-cicd', topic: 'CI/CD', sub: 'Operación', difficulty: 3,
    q: 'Nombrá tres estrategias de despliegue y su tradeoff.',
    a: 'Rolling update: reemplaza instancias de a poco, sin infraestructura extra pero con dos versiones conviviendo. Blue-green: dos entornos y switch inmediato, rollback trivial pero costo doble. Canary: expone un porcentaje al cambio, detecta temprano pero requiere métricas y enrutamiento por peso.',
    example: 'kubectl set image deployment/api api=app:1.4\nkubectl rollout status deployment/api',
    misconceptions: ['Creer que canary es solo "desplegar y ver"', 'No tener métricas para decidir el corte'],
    related: ['c-rollback', 'c-slo'], tags: ['cicd', 'k8s'] },

  /* ---------- Día 2 · Actions ---------- */
  { id: 'c-actions-on', module: 'd2-actions', topic: 'CI/CD', sub: 'Actions', difficulty: 2,
    q: '¿Qué eventos se usan habitualmente en on de GitHub Actions?',
    a: 'push (con filtro de branches), pull_request, workflow_dispatch para ejecución manual, schedule con cron y release o tags. Los permisos del GITHUB_TOKEN se declaran aparte con permissions.',
    example: 'on:\n  push: { branches: [main] }\n  pull_request:\n  workflow_dispatch:',
    misconceptions: ['Ejecutar deploy en cualquier push de cualquier rama', 'Olvidar pull_request y no validar antes del merge'],
    related: ['c-actions-needs', 'c-actions-perm'], tags: ['cicd', 'actions'] },
  { id: 'c-actions-needs', module: 'd2-actions', topic: 'CI/CD', sub: 'Actions', difficulty: 2,
    q: '¿Cómo se ordenan jobs en GitHub Actions?',
    a: 'Con needs. Sin needs, los jobs corren en paralelo en runners separados. Cada job empieza en un runner limpio, por lo que los archivos se comparten con artifacts, no con el filesystem.',
    example: 'jobs:\n  test: ...\n  build:\n    needs: test',
    misconceptions: ['Asumir orden secuencial por escribirlos en orden', 'Esperar archivos de un job anterior sin artifact'],
    related: ['c-artifacts', 'c-actions-on'], tags: ['cicd', 'actions'] },
  { id: 'c-actions-matrix', module: 'd2-actions', topic: 'CI/CD', sub: 'Actions', difficulty: 3,
    q: '¿Qué es una matrix en GitHub Actions?',
    a: 'Una forma de ejecutar la misma job con combinaciones de variables (versiones de Node, SO) en paralelo. Cada combinación es un job independiente; fail-fast puede cancelar el resto al primer fallo.',
    example: 'strategy:\n  matrix:\n    node: [18, 20, 22]',
    misconceptions: ['Creer que matrix ejecuta secuencialmente', 'No fijar fail-fast según el caso'],
    related: ['c-actions-needs', 'c-actions-on'], tags: ['cicd', 'actions'] },
  { id: 'c-actions-secrets', module: 'd2-actions', topic: 'CI/CD', sub: 'Actions', difficulty: 2,
    q: '¿Cómo se manejan secretos en GitHub Actions?',
    a: 'Se guardan en Settings → Secrets (o environments para producción) y se referencian con secrets.NOMBRE. Nunca se imprimen; GitHub los enmascara en logs. Para mayor seguridad se usan environments con aprobación y OIDC en lugar de claves de nube de larga duración.',
    example: 'env:\n  TOKEN: ${{ secrets.GHCR_TOKEN }}',
    misconceptions: ['Escribir secretos en el YAML', 'Usar el mismo secreto para todos los ambientes'],
    related: ['c-secrets', 'c-actions-perm'], tags: ['cicd', 'seguridad'] },
  { id: 'c-artifacts', module: 'd2-actions', topic: 'CI/CD', sub: 'Actions', difficulty: 2,
    q: '¿Cómo se pasan archivos entre jobs en Actions?',
    a: 'Con upload-artifact en el job productor y download-artifact en el consumidor. Los artifacts tienen retención configurable y sirven también como evidencia de build (binarios, reportes de test, SBOM).',
    example: '- uses: actions/upload-artifact@v4\n  with: { name: dist, path: dist/ }',
    misconceptions: ['Intentar leer el workspace de otro job', 'Subir node_modules como artifact'],
    related: ['c-actions-needs', 'c-artifact'], tags: ['cicd', 'actions'] },
  { id: 'c-actions-perm', module: 'd2-actions', topic: 'CI/CD', sub: 'Actions', difficulty: 3,
    q: '¿Por qué declarar permissions: contents: read en un workflow?',
    a: 'Porque el GITHUB_TOKEN tiene permisos por defecto que pueden ser amplios. Declararlos explícitamente al mínimo necesario reduce el impacto de un step comprometido (por ejemplo, una action de terceros).',
    example: 'permissions:\n  contents: read\n  packages: write',
    misconceptions: ['Dejar permisos por defecto en workflows con actions de terceros', 'Dar write a todo el workflow'],
    related: ['c-actions-secrets', 'c-sev-gate'], tags: ['cicd', 'seguridad'] },

  /* ---------- Día 2 · Registries ---------- */
  { id: 'c-latest', module: 'd2-registries', topic: 'Docker', sub: 'Registries', difficulty: 2,
    q: '¿Por qué no usar el tag latest en producción?',
    a: 'latest es un tag mutable: no identifica una versión y puede cambiar sin que tu pipeline lo sepa, produciendo despliegues no reproducibles. Se usan tags semánticos y el SHA del commit; para máxima garantía, el digest.',
    example: 'docker build -t ghcr.io/ana/api:1.4.2 -t ghcr.io/ana/api:sha-9f2c1a .',
    misconceptions: ['Creer que latest es la imagen más nueva garantizada', 'Desplegar latest y no poder rollbackear'],
    related: ['c-digest', 'c-artifact'], tags: ['docker', 'registries'] },
  { id: 'c-digest', module: 'd2-registries', topic: 'Docker', sub: 'Registries', difficulty: 3,
    q: '¿Qué es el digest de una imagen?',
    a: 'Un hash sha256 del contenido de la imagen, inmutable. Permite referenciar exactamente lo construido aunque el tag se reescriba. Docker lo muestra en RepoDigests al inspeccionar.',
    example: 'docker inspect ghcr.io/ana/api:1.4.2 --format "{{.RepoDigests}}"',
    misconceptions: ['Confundir digest con tag', 'Creer que el digest cambia al reetiquetar'],
    related: ['c-latest', 'c-artifact'], tags: ['docker', 'registries', 'seguridad'] },
  { id: 'c-registry-login', module: 'd2-registries', topic: 'Docker', sub: 'Registries', difficulty: 2,
    q: '¿Cómo autenticás Docker contra un registry en CI?',
    a: 'Con docker login usando usuario y un token con permiso de push, pasando la contraseña por stdin para no dejarla en el historial: echo $TOKEN | docker login ghcr.io -u usuario --password-stdin. En Actions se usa docker/login-action con secrets.',
    example: 'echo "$GHCR_TOKEN" | docker login ghcr.io -u ana --password-stdin',
    misconceptions: ['Poner la contraseña en el comando', 'Usar el token como variable de entorno global visible'],
    related: ['c-actions-secrets', 'c-secrets'], tags: ['docker', 'registries', 'seguridad'] },
  { id: 'c-promotion', module: 'd2-registries', topic: 'Docker', sub: 'Registries', difficulty: 3,
    q: '¿Cómo se promociona una imagen entre dev, staging y producción?',
    a: 'Se construye una vez con un tag inmutable (SHA o versión), se publica en el registry y cada ambiente referencia el mismo digest. La promoción es cambiar la referencia del ambiente, no reconstruir.',
    example: 'docker pull app@sha256:...\nkubectl set image deployment/api api=app@sha256:...',
    misconceptions: ['Reconstruir por ambiente', 'Usar tags distintos para el mismo build'],
    related: ['c-digest', 'c-artifact'], tags: ['docker', 'cicd'] },

  /* ---------- Día 3 · Cloud ---------- */
  { id: 'c-iaas', module: 'd3-cloud', topic: 'Cloud', sub: 'Modelos', difficulty: 2,
    q: '¿Diferencia entre IaaS, PaaS y SaaS?',
    a: 'IaaS entrega máquinas, red y almacenamiento (máximo control, máxima operación). PaaS entrega plataforma para desplegar la app sin administrar el SO. SaaS es software listo para usar, sin gestión de infraestructura.',
    example: 'IaaS: EC2. PaaS: App Service. SaaS: Gmail / Slack.',
    misconceptions: ['Pensar que PaaS no tiene límites operativos', 'Elegir IaaS por defecto para todo'],
    related: ['c-az', 'c-subnet'], tags: ['cloud'] },
  { id: 'c-az', module: 'd3-cloud', topic: 'Cloud', sub: 'Arquitectura', difficulty: 2,
    q: '¿Qué es una Availability Zone y qué implica para el diseño?',
    a: 'Es un datacenter (o grupo) con energía y red independientes dentro de una región. Para alta disponibilidad, las instancias se distribuyen en al menos dos AZ detrás de un balanceador. Multi-AZ protege contra fallos de una zona, no contra borrados ni errores de aplicación.',
    example: 'ALB en 2 subnets públicas, ASG con instancias en 2 AZ, RDS Multi-AZ.',
    misconceptions: ['Confundir Multi-AZ con backup', 'Poner todo en una sola AZ y llamarlo HA'],
    related: ['c-iaas', 'c-subnet'], tags: ['cloud', 'disponibilidad'] },
  { id: 'c-secret-leak', module: 'd4-devsecops', topic: 'DevSecOps', sub: 'Secretos', difficulty: 3,
    q: '¿Qué pasos seguís ante un secreto commiteado?',
    a: '1) Rotar/revocar inmediatamente. 2) Buscar uso indebido en logs de acceso. 3) Eliminar de la historia con filter-repo y coordinar el force push. 4) Añadir gitleaks en pre-commit y CI. 5) Documentar el incidente.',
    example: 'gitleaks detect --source . -v\naws iam update-access-key / consola del proveedor',
    misconceptions: ['Solo borrar el archivo en un commit nuevo', 'Rotar sin revisar accesos'],
    related: ['c-git-secret', 'c-secrets'], tags: ['seguridad', 'git'] },
  { id: 'c-secrets', module: 'd4-devsecops', topic: 'DevSecOps', sub: 'Secretos', difficulty: 2,
    q: '¿Dónde se guardan los secretos en un pipeline y en Kubernetes?',
    a: 'En el CI: secrets del proveedor o gestor externo (Vault, AWS Secrets Manager). En Kubernetes: Secret (base64, requiere cifrado en etcd o gestor externo), Sealed Secrets o External Secrets. Nunca en Git, imagen ni logs.',
    example: 'kubectl create secret generic db --from-literal=password=...\nkubectl get secret db -o jsonpath=\'{.data.password}\' | base64 -d',
    misconceptions: ['Creer que base64 es cifrado', 'Guardar secretos en ConfigMap'],
    related: ['c-secret-leak', 'c-k8s-config'], tags: ['seguridad', 'k8s'] },

  /* ---------- Día 3 · Terraform ---------- */
  { id: 'c-tfstate', module: 'd3-terraform', topic: 'Terraform', sub: 'State', difficulty: 3,
    q: '¿Qué es el state de Terraform y por qué no se commitea?',
    a: 'Es el archivo que mapea recursos declarados con los IDs reales del proveedor. Sin él, Terraform no sabe qué administra y duplicaría recursos. No se commitea porque puede contener datos sensibles y porque en equipo necesita backend remoto con lock.',
    example: 'backend "s3" { bucket = "tf-state" key = "prod/terraform.tfstate" dynamodb_table = "tf-lock" }',
    misconceptions: ['Subir tfstate a Git', 'Ejecutar apply desde dos máquinas sin lock'],
    related: ['c-tf-state-cmd', 'c-drift'], tags: ['terraform', 'estado'] },
  { id: 'c-tf-state-cmd', module: 'd3-terraform', topic: 'Terraform', sub: 'State', difficulty: 3,
    q: '¿Qué comandos usás para inspeccionar o mover recursos en el state?',
    a: 'terraform state list lista recursos; state show muestra atributos; state mv mueve un recurso a otra dirección sin recrearlo; import incorpora infraestructura existente; state rm deja de gestionar sin destruir.',
    example: 'terraform state list\nterraform state mv aws_instance.a aws_instance.web',
    misconceptions: ['Editar el state a mano', 'Usar rm creyendo que destruye el recurso'],
    related: ['c-tfstate', 'c-drift'], tags: ['terraform', 'estado'] },
  { id: 'c-tf-plan', module: 'd3-terraform', topic: 'Terraform', sub: 'Workflow', difficulty: 2,
    q: '¿Por qué se revisa el plan antes del apply?',
    a: 'Porque el plan muestra exactamente qué se creará, cambiará o destruirá, incluyendo reemplazos de recursos. Un cambio aparentemente inocente puede implicar destroy de una base de datos. Guardar el plan (-out) garantiza aplicar lo revisado.',
    example: 'terraform plan -out=tfplan\nterraform show tfplan\nterraform apply tfplan',
    misconceptions: ['Aprobar sin leer signos -/+', 'Aplicar sin plan en producción'],
    related: ['c-tfstate', 'c-tf-lifecycle'], tags: ['terraform'] },
  { id: 'c-drift', module: 'd3-terraform', topic: 'Terraform', sub: 'Estado', difficulty: 3,
    q: '¿Qué es el drift y cómo se gestiona?',
    a: 'Es la diferencia entre el estado deseado (código) y la realidad, normalmente por cambios manuales en la consola. Se detecta con terraform plan; se corrige aplicando para volver al código, o importando el cambio si es intencional.',
    example: 'terraform plan -detailed-exitcode   # 2 = hay diferencias',
    misconceptions: ['Hacer clickops y esperar que Terraform lo adopte', 'Ignorar el drift en producción'],
    related: ['c-tfstate', 'c-tf-state-cmd'], tags: ['terraform', 'operacion'] },
  { id: 'c-tf-lifecycle', module: 'd3-terraform', topic: 'Terraform', sub: 'State', difficulty: 3,
    q: '¿Para qué sirve lifecycle prevent_destroy?',
    a: 'Bloquea el destroy de un recurso sensible (por ejemplo una base de datos) aunque el plan lo indique. Es una protección contra errores humanos; se complementa con backups y con revisión del plan.',
    example: 'lifecycle { prevent_destroy = true }',
    misconceptions: ['Creer que protege contra pérdida de datos por otras causas', 'Dejarlo en recursos que deben recrearse'],
    related: ['c-tf-plan', 'c-drift'], tags: ['terraform', 'seguridad'] },
  { id: 'c-tf-modules', module: 'd3-terraform', topic: 'Terraform', sub: 'Organización', difficulty: 2,
    q: '¿Qué son variables, outputs y módulos en Terraform?',
    a: 'Las variables parametrizan la configuración (con type, default y validation); los outputs exponen valores para otros módulos o scripts; los módulos empaquetan recursos reutilizables con entradas y salidas. locals evita repetir expresiones.',
    example: 'variable "env" { type = string, default = "dev" }\noutput "bucket" { value = aws_s3_bucket.logs.bucket }',
    misconceptions: ['Duplicar código en lugar de módulos', 'Usar variables sin validación'],
    related: ['c-tfstate', 'c-tf-plan'], tags: ['terraform', 'organizacion'] },

  /* ---------- Día 3 · Kubernetes ---------- */
  { id: 'c-k8s-cp', module: 'd3-k8s-arq', topic: 'Kubernetes', sub: 'Arquitectura', difficulty: 3,
    q: '¿Qué componentes forman el control plane y qué hace cada uno?',
    a: 'kube-apiserver (única API, valida y persiste), etcd (estado del clúster), kube-scheduler (asigna Pods a nodos), kube-controller-manager (controladores de reconciliación) y cloud-controller-manager (integración con el proveedor).',
    example: 'kubectl get --raw /healthz\nkubectl get componentstatuses   # según versión',
    misconceptions: ['Confundir scheduler con kubelet', 'Creer que el apiserver guarda el estado en un archivo local'],
    related: ['c-k8s-etcd', 'c-k8s-reconcile'], tags: ['k8s', 'arquitectura'] },
  { id: 'c-k8s-etcd', module: 'd3-k8s-arq', topic: 'Kubernetes', sub: 'Arquitectura', difficulty: 3,
    q: '¿Por qué etcd es crítico y qué implica su pérdida?',
    a: 'etcd es la base clave-valor que contiene todo el estado del clúster. Si se pierde sin backup, se pierde el clúster (objetos, configuración, secretos). Requiere backups consistentes y quorum en despliegues multi-nodo.',
    example: 'kubectl get pods -n kube-system | grep etcd',
    misconceptions: ['Respaldar solo los YAML y no etcd', 'Ignorar el quorum en clústeres con 2 nodos de etcd'],
    related: ['c-k8s-cp', 'c-k8s-reconcile'], tags: ['k8s', 'arquitectura', 'backup'] },
  { id: 'c-k8s-reconcile', module: 'd3-k8s-arq', topic: 'Kubernetes', sub: 'Arquitectura', difficulty: 2,
    q: '¿Qué es el bucle de reconciliación?',
    a: 'El control plane compara continuamente el estado deseado (declarado en objetos) con el real y actúa para igualarlos: ReplicaSet crea Pods, kube-scheduler los ubica y kubelet los ejecuta. Por eso borrar un Pod de un Deployment lo recrea.',
    example: 'kubectl get deploy web -o yaml | grep replicas\nkubectl delete pod web-abc   # el ReplicaSet crea otro',
    misconceptions: ['Esperar que un Pod borrado no vuelva', 'Editar Pods en lugar del controlador'],
    related: ['c-k8s-workloads', 'c-k8s-cp'], tags: ['k8s', 'arquitectura'] },
  { id: 'c-k8s-workloads', module: 'd3-k8s-arq', topic: 'Kubernetes', sub: 'Objetos', difficulty: 3,
    q: '¿Cuándo usás Deployment, StatefulSet, DaemonSet o Job?',
    a: 'Deployment para servicios sin estado con réplicas intercambiables; StatefulSet para identidad estable y almacenamiento por réplica (bases de datos); DaemonSet para un Pod por nodo (agentes); Job/CronJob para tareas finitas o programadas.',
    example: 'kubectl create deployment web --image=nginx --replicas=2',
    misconceptions: ['Usar Deployment para una base de datos con datos persistentes', 'Usar Job para un servicio que debe seguir corriendo'],
    related: ['c-k8s-reconcile', 'c-k8s-deploy'], tags: ['k8s', 'objetos'] },
  { id: 'c-k8s-limits', module: 'd3-k8s-arq', topic: 'Kubernetes', sub: 'Recursos', difficulty: 3,
    q: '¿Diferencia entre requests y limits?',
    a: 'requests es lo que el scheduler reserva para ubicar el Pod y garantiza disponibilidad; limits es el tope en runtime. Superar el límite de memoria provoca OOMKilled (137); de CPU produce throttling.',
    example: 'resources:\n  requests: { cpu: 100m, memory: 128Mi }\n  limits: { cpu: 500m, memory: 256Mi }',
    misconceptions: ['Poner limits sin requests', 'Subir memoria indiscriminadamente sin analizar leaks'],
    related: ['c-oom', 'c-k8s-hpa'], tags: ['k8s', 'recursos'] },
  { id: 'c-k8s-hpa', module: 'd3-k8s-arq', topic: 'Kubernetes', sub: 'Escalado', difficulty: 3,
    q: '¿Qué hace el HPA y qué necesita para funcionar?',
    a: 'Ajusta la cantidad de réplicas según métricas (CPU, memoria o custom). Necesita metrics-server o un adaptador de métricas, requests definidos en los contenedores y un Deployment escalable.',
    example: 'kubectl autoscale deployment web --cpu-percent=70 --min=2 --max=10',
    misconceptions: ['Esperar que HPA escale sin metrics-server', 'Escalar sin requests y obtener métricas erróneas'],
    related: ['c-k8s-limits', 'c-k8s-deploy'], tags: ['k8s', 'escalado'] },

  /* ---------- Día 3 · Services/probes ---------- */
  { id: 'c-k8s-service', module: 'd3-k8s-workloads', topic: 'Kubernetes', sub: 'Networking', difficulty: 2,
    q: '¿Cómo encuentra un Service a los Pods?',
    a: 'Por label selector: mantiene endpoints con los Pods que matchean labels y están Ready. La IP del Service es estable aunque los Pods cambien. Si no hay endpoints, el selector no matchea o los Pods no están listos.',
    example: 'kubectl get svc web\nkubectl get endpoints web',
    misconceptions: ['Creer que el Service apunta a una IP fija de Pod', 'Ignorar labels en el selector'],
    related: ['c-k8s-endpoints', 'c-k8s-ingress'], tags: ['k8s', 'redes'] },
  { id: 'c-k8s-endpoints', module: 'd3-k8s-workloads', topic: 'Kubernetes', sub: 'Networking', difficulty: 3,
    q: 'Un Service devuelve connection refused. ¿Qué revisás?',
    a: 'Primero endpoints: si está vacío, el selector o la readiness fallan. Luego targetPort vs containerPort (desajuste típico). Después label del Pod, que el contenedor escuche en 0.0.0.0 y que la app esté viva. Se prueba desde un Pod con wget o curl.',
    example: 'kubectl get endpoints web\nkubectl describe svc web\nkubectl exec -it tmp -- wget -qO- http://web',
    misconceptions: ['Reiniciar el Deployment sin revisar endpoints', 'Confundir port con targetPort'],
    related: ['c-k8s-service', 'c-probes'], tags: ['k8s', 'troubleshooting'] },
  { id: 'c-probes', module: 'd3-k8s-workloads', topic: 'Kubernetes', sub: 'Salud', difficulty: 3,
    q: '¿Diferencia entre liveness, readiness y startup probe?',
    a: 'liveness: si falla, reinicia el contenedor (proceso colgado). readiness: si falla, lo saca de los endpoints sin reiniciar. startup: da tiempo de arranque y bloquea las otras hasta que pase. Usar el mismo endpoint para liveness y readiness puede causar reinicios en cascada.',
    example: 'livenessProbe: { httpGet: { path: /healthz, port: 8080 }, periodSeconds: 10 }\nreadinessProbe: { httpGet: { path: /ready, port: 8080 } }',
    misconceptions: ['Poner liveness apuntando a la base de datos', 'No usar readiness y enviar tráfico a Pods que arrancan'],
    related: ['c-k8s-endpoints', 'c-k8s-crash'], tags: ['k8s', 'salud'] },
  { id: 'c-k8s-ingress', module: 'd3-k8s-workloads', topic: 'Kubernetes', sub: 'Networking', difficulty: 3,
    q: '¿Qué hace un Ingress y qué necesita para funcionar?',
    a: 'Enruta tráfico HTTP/HTTPS externo a Services según host y path. Requiere un Ingress Controller desplegado (nginx, traefik) y, en cloud, un LoadBalancer delante. TLS se configura con Secrets.',
    example: 'kubectl get ingress\nkubectl describe ingress web',
    misconceptions: ['Creer que Ingress funciona sin controller', 'Confundir Ingress con Service LoadBalancer'],
    related: ['c-k8s-service', 'c-k8s-config'], tags: ['k8s', 'redes'] },
  { id: 'c-k8s-config', module: 'd3-k8s-workloads', topic: 'Kubernetes', sub: 'Configuración', difficulty: 2,
    q: '¿Diferencia entre ConfigMap y Secret?',
    a: 'ConfigMap guarda configuración no sensible en texto plano. Secret está pensado para datos sensibles: se codifica en base64 (no cifra) y requiere cifrado en etcd o un gestor externo. Ambos se inyectan como env o volumen.',
    example: 'kubectl create configmap app --from-literal=LOG_LEVEL=info\nkubectl create secret generic db --from-literal=pass=...',
    misconceptions: ['Tratar base64 como cifrado', 'Poner contraseñas en ConfigMap'],
    related: ['c-secrets', 'c-k8s-ingress'], tags: ['k8s', 'configuracion'] },
  { id: 'c-k8s-crash', module: 'd3-k8s-workloads', topic: 'Kubernetes', sub: 'Troubleshooting', difficulty: 3,
    q: '¿Cómo diagnosticás un CrashLoopBackOff?',
    a: 'CrashLoopBackOff es un síntoma: el contenedor arranca y muere repetidamente. Se revisa kubectl logs (y --previous), describe para ver eventos y exit code, y causas típicas: error de app (1), OOMKilled (137), comando o imagen inexistente, config o secret faltante, probe mal configurada.',
    example: 'kubectl logs api-abc --previous\nkubectl describe pod api-abc | tail -25',
    misconceptions: ['Reiniciar el pod como solución', 'Mirar solo logs actuales y no los del contenedor anterior'],
    related: ['c-probes', 'c-exit-codes'], tags: ['k8s', 'troubleshooting'] },
  { id: 'c-k8s-logs', module: 'd3-k8s-workloads', topic: 'Kubernetes', sub: 'Troubleshooting', difficulty: 2,
    q: '¿Cómo obtenés logs de un Pod con varias réplicas o contenedores?',
    a: 'kubectl logs deploy/api para el deployment (una réplica), -c nombre para un contenedor específico, --previous para el anterior, -f para seguir y --since para acotar. En varias réplicas se usa -l app=api --max-log-requests o stern.',
    example: 'kubectl logs -l app=api --since=10m --tail=100',
    misconceptions: ['Buscar logs solo con kubectl logs sin selector', 'Ignorar logs del contenedor que reinició'],
    related: ['c-k8s-crash', 'c-docker-logs'], tags: ['k8s', 'logs'] },
  { id: 'c-k8s-deploy', module: 'd3-k8s-workloads', topic: 'Kubernetes', sub: 'Despliegue', difficulty: 2,
    q: '¿Cómo se hace un rollout y cómo se revierte?',
    a: 'Se actualiza la imagen en el Deployment (kubectl set image o apply) y se sigue con rollout status. Con rollout undo se vuelve a la revisión anterior; rollout history lista revisiones. maxSurge y maxUnavailable controlan el ritmo.',
    example: 'kubectl set image deployment/api api=app:1.4.0\nkubectl rollout status deployment/api\nkubectl rollout undo deployment/api',
    misconceptions: ['Editar Pods directamente', 'No fijar revisión ni imagen para el rollback'],
    related: ['c-k8s-workloads', 'c-deploy-strategies'], tags: ['k8s', 'despliegue'] },

  /* ---------- Día 4 · Observabilidad ---------- */
  { id: 'c-signals', module: 'd4-observabilidad', topic: 'Observabilidad', sub: 'Fundamentos', difficulty: 2,
    q: '¿Cuándo usás métricas, logs y trazas?',
    a: 'Métricas para tendencias, alertas y SLOs (agregadas y baratas). Logs para causas puntuales con contexto detallado. Trazas para seguir una request entre servicios y encontrar el tramo lento. Se complementan: métrica detecta, traza ubica, log explica.',
    example: 'Grafana (métrica) → Jaeger (traza) → Loki (log)',
    misconceptions: ['Alertar solo con logs', 'Creer que las trazas reemplazan a las métricas'],
    related: ['c-promql', 'c-slo'], tags: ['observabilidad'] },
  { id: 'c-promql', module: 'd4-observabilidad', topic: 'Observabilidad', sub: 'Prometheus', difficulty: 3,
    q: '¿Qué hace rate(http_requests_total[5m]) y por qué no usar el contador directo?',
    a: 'Calcula la tasa por segundo de un contador en una ventana de 5 minutos. Los contadores solo crecen (y se reinician al reiniciar el proceso), así que el valor absoluto no sirve para alertar; la tasa sí refleja tráfico actual.',
    example: 'sum(rate(http_requests_total[5m])) by (status)',
    misconceptions: ['Alertar sobre el valor absoluto del contador', 'Usar ventanas demasiado cortas y obtener ruido'],
    related: ['c-p95', 'c-slo'], tags: ['observabilidad', 'promql'] },
  { id: 'c-p95', module: 'd4-observabilidad', topic: 'Observabilidad', sub: 'Prometheus', difficulty: 3,
    q: '¿Por qué p95 es más útil que el promedio de latencia?',
    a: 'El promedio esconde la cola: si el 5% de usuarios espera 8 segundos y el resto 100 ms, el promedio parece sano. p95 muestra que el 5% más lento sufre, que es lo que perciben los usuarios afectados.',
    example: 'histogram_quantile(0.95, sum(rate(http_request_duration_seconds_bucket[5m])) by (le))',
    misconceptions: ['Reportar solo promedio', 'Interpretar p95 como el 95% de las requests más lentas'],
    related: ['c-promql', 'c-slo'], tags: ['observabilidad'] },
  { id: 'c-slo', module: 'd4-observabilidad', topic: 'Observabilidad', sub: 'SLO', difficulty: 3,
    q: '¿Qué son SLI, SLO y error budget?',
    a: 'SLI es la medida (porcentaje de requests exitosas). SLO es el objetivo (99.9% en 30 días). Error budget es el margen permitido de fallo (0.1%); si se agota, se prioriza estabilidad. Sin SLO, las alertas no tienen umbral de negocio.',
    example: 'SLO 99.9% mensual → error budget ≈ 43 minutos de caída.',
    misconceptions: ['Confundir SLA (contrato) con SLO (objetivo interno)', 'Definir SLO sin medir el SLI'],
    related: ['c-signals', 'c-alertas'], tags: ['observabilidad', 'sre'] },
  { id: 'c-alertas', module: 'd4-observabilidad', topic: 'Observabilidad', sub: 'Alertas', difficulty: 2,
    q: '¿Qué hace útil a una alerta y qué genera fatiga?',
    a: 'Útil: se basa en síntoma de usuario (latencia, tasa de error, disponibilidad), tiene umbral, duración (for), severidad, runbook y dueño. Fatiga: alertas por cada métrica, umbrales sin contexto y alertas que se silencian siempre.',
    example: 'alert: HighErrorRate\nexpr: rate(http_requests_total{status=~"5.."}[5m]) / rate(http_requests_total[5m]) > 0.05\nfor: 10m',
    misconceptions: ['Alertar por CPU al 80% sin impacto', 'Sin for y disparar con un pico de un scrape'],
    related: ['c-slo', 'c-promql'], tags: ['observabilidad', 'alertas'] },
  { id: 'c-up', module: 'd4-observabilidad', topic: 'Observabilidad', sub: 'Prometheus', difficulty: 2,
    q: '¿Qué indica la métrica up == 0 en Prometheus?',
    a: 'Que Prometheus no pudo scrapear un target: el endpoint /metrics no responde, el servicio está caído o hay un problema de red/descubrimiento. Es la alerta básica de disponibilidad, pero no distingue si la app está lenta o mal configurada.',
    example: 'up == 0\ncount by (job) (up == 0)',
    misconceptions: ['Creer que up mide si la app funciona correctamente', 'Ignorar targets caídos por scrape fallido'],
    related: ['c-alertas', 'c-signals'], tags: ['observabilidad'] },

  /* ---------- Día 4 · DevSecOps ---------- */
  { id: 'c-sast', module: 'd4-devsecops', topic: 'DevSecOps', sub: 'Herramientas', difficulty: 2,
    q: '¿Diferencia entre SAST, DAST y SCA?',
    a: 'SAST analiza el código fuente sin ejecutarlo (inyecciones, patrones inseguros). DAST prueba la aplicación en ejecución como lo haría un atacante. SCA revisa dependencias contra bases de vulnerabilidades conocidas.',
    example: 'SAST: Semgrep/CodeQL. DAST: OWASP ZAP. SCA: Dependabot/Trivy/npm audit.',
    misconceptions: ['Creer que SAST encuentra todo', 'Escanear dependencias solo en producción'],
    related: ['c-sev-gate', 'c-secret-leak'], tags: ['seguridad', 'devsecops'] },
  { id: 'c-sev-gate', module: 'd4-devsecops', topic: 'DevSecOps', sub: 'Pipeline', difficulty: 3,
    q: '¿Qué hallazgos de seguridad deberían bloquear un merge?',
    a: 'Críticos explotables con fix disponible, secretos detectados y configuraciones IAM/red peligrosas (bucket público, 0.0.0.0/0 en SSH). Hallazgos medios sin fix se registran con excepción y fecha de revisión; si todo bloquea, el equipo busca bypass.',
    example: 'Trivy --severity CRITICAL --exit-code 1\ngitleaks detect --exit-code 1',
    misconceptions: ['Bloquear cualquier hallazgo y forzar excepciones', 'Ignorar todo hasta la auditoría'],
    related: ['c-sast', 'c-actions-perm'], tags: ['seguridad', 'cicd'] },
  { id: 'c-sbom', module: 'd4-devsecops', topic: 'DevSecOps', sub: 'Supply chain', difficulty: 3,
    q: '¿Qué es un SBOM y para qué sirve?',
    a: 'Software Bill of Materials: inventario de componentes y versiones de una imagen o aplicación. Permite responder rápido ante una CVE nueva (¿usamos esa librería?), cumplir requisitos y auditar la cadena de suministro. Se genera con syft o trivy y se firma con cosign.',
    example: 'syft miapp:1.0 -o spdx-json > sbom.json\ntrivy sbom sbom.json',
    misconceptions: ['Confundir SBOM con escaneo', 'No versionar el SBOM con el artefacto'],
    related: ['c-sast', 'c-sev-gate'], tags: ['seguridad', 'supply-chain'] },
  { id: 'c-container-hardening', module: 'd4-devsecops', topic: 'DevSecOps', sub: 'Contenedores', difficulty: 3,
    q: 'Nombrá cuatro medidas de hardening de contenedores.',
    a: 'Usuario no-root, imagen base mínima y fija, filesystem read-only y capabilities reducidas. Sumado a: no montar docker.sock, límites de recursos, escaneo de imagen y NetworkPolicies en Kubernetes.',
    example: 'docker run --user 1000 --read-only --cap-drop ALL --security-opt no-new-privileges miapp:1.0',
    misconceptions: ['Usar --privileged por comodidad', 'Montar el socket de Docker dentro del contenedor'],
    related: ['c-user', 'c-k8s-config'], tags: ['seguridad', 'docker'] },
  { id: 'c-iam-least', module: 'd4-devsecops', topic: 'DevSecOps', sub: 'IAM', difficulty: 2,
    q: '¿Cómo se aplica menor privilegio en la nube?',
    a: 'Roles con políticas específicas por recurso y acción, condiciones cuando aplique, MFA para humanos, credenciales temporales (OIDC) en CI y revisión periódica de permisos no usados. Nunca claves de larga duración en el código.',
    example: 'política: s3:PutObject sobre arn:aws:s3:::mi-bucket/uploads/*',
    misconceptions: ['Dar AdministratorAccess al pipeline', 'Compartir un único usuario para todos los servicios'],
    related: ['c-iam-role', 'c-secret-leak'], tags: ['seguridad', 'cloud'] },

  /* ---------- Día 4 · Troubleshooting ---------- */
  { id: 'c-ts-method', module: 'd4-troubleshooting', topic: 'Troubleshooting', sub: 'Método', difficulty: 2,
    q: '¿Cuál es el primer paso al recibir un incidente?',
    a: 'Definir el síntoma con datos y acotar el alcance: desde cuándo, a quién afecta, qué porcentaje, qué error exacto. Después formular hipótesis ordenadas y verificar con evidencia. Sin ese encuadre, se prueba al azar.',
    example: '¿Qué cambió? ¿Cuándo empezó? ¿Afecta a todos los usuarios o a una región?',
    misconceptions: ['Empezar reiniciando servicios', 'Asumir la causa sin evidencia'],
    related: ['c-ts-rca', 'c-ts-comms'], tags: ['troubleshooting'] },
  { id: 'c-ts-rca', module: 'd4-troubleshooting', topic: 'Troubleshooting', sub: 'Método', difficulty: 3,
    q: '¿Diferencia entre mitigación y causa raíz?',
    a: 'Mitigación recupera el servicio (rollback, restart, failover) aunque la causa siga presente. La causa raíz se investiga después, con el servicio estable, y se corrige con un cambio verificable. Confundirlas hace que el incidente vuelva.',
    example: 'Mitigación: kubectl rollout undo. RCA: la nueva versión tenía una consulta N+1.',
    misconceptions: ['Cerrar el incidente tras reiniciar', 'Buscar la causa raíz con el servicio caído'],
    related: ['c-ts-method', 'c-rollback'], tags: ['troubleshooting'] },
  { id: 'c-ts-comms', module: 'd4-troubleshooting', topic: 'Troubleshooting', sub: 'Comunicación', difficulty: 2,
    q: '¿Cómo se comunica un incidente en curso?',
    a: 'Impacto (qué no funciona y para quién), estado (investigando, mitigando, resuelto), acción actual y próxima actualización. Sin especulación ni culpas. Actualizaciones periódicas aunque no haya novedades.',
    example: 'Impacto: 30% de usuarios no puede iniciar sesión. Estado: mitigando. Acción: rollback del servicio auth. Próxima actualización: 15 min.',
    misconceptions: ['Dar detalles técnicos sin impacto', 'Prometer una hora de resolución sin evidencia'],
    related: ['c-ts-method', 'c-ts-rca'], tags: ['troubleshooting', 'comunicacion'] },
  { id: 'c-ts-disk', module: 'd4-troubleshooting', topic: 'Troubleshooting', sub: 'Recursos', difficulty: 2,
    q: 'Un servidor reporta disco lleno. ¿Cómo lo diagnosticás?',
    a: 'df -h para ver el filesystem afectado, df -i para inodos, du -sh /var/* | sort -h para ubicar los directorios grandes, y lsof +L1 para archivos borrados que siguen abiertos. Se limpian logs con rotación, no borrando a ciegas.',
    example: 'df -h; df -i\ndu -sh /var/* 2>/dev/null | sort -h | tail -5\nsudo lsof +L1 | head',
    misconceptions: ['Borrar logs activos sin reiniciar el proceso', 'Ignorar el agotamiento de inodos'],
    related: ['c-var', 'c-ts-method'], tags: ['troubleshooting', 'disco'] },
  { id: 'c-ts-502', module: 'd4-troubleshooting', topic: 'Troubleshooting', sub: 'Red', difficulty: 3,
    q: 'Un nginx devuelve 502. ¿Cuál es la secuencia de diagnóstico?',
    a: 'Leer el error log de nginx (connection refused, timeout, host no resuelto), verificar que el upstream esté escuchando (ss -tulpn), probar el upstream directamente (curl), revisar el puerto en la config y, si está en contenedor/K8s, endpoints y targetPort.',
    example: 'tail -f /var/log/nginx/error.log\nss -tulpn | grep 3000\ncurl -I http://127.0.0.1:3000',
    misconceptions: ['Reiniciar nginx sin leer el error log', 'Culpar a DNS sin probar el upstream'],
    related: ['c-502', 'c-k8s-endpoints'], tags: ['troubleshooting', 'redes'] },
  { id: 'c-ts-load', module: 'd4-troubleshooting', topic: 'Troubleshooting', sub: 'Recursos', difficulty: 3,
    q: '¿Qué revisás ante un load average alto con CPU baja?',
    a: 'Sospechar I/O: procesos en estado D, iostat o iotop, dispositivos lentos, NFS caído, o límites de IOPS en cloud. También revisar memoria y swap (swapping genera espera) y procesos zombies.',
    example: 'vmstat 1 5\niostat -x 1 3\ndstat 1 5',
    misconceptions: ['Asumir falta de CPU', 'Ignorar la espera de I/O en el load'],
    related: ['c-load', 'c-proc-states'], tags: ['troubleshooting', 'rendimiento'] },

  /* ---------- Día 4 · Entrevista ---------- */
  { id: 'c-star', module: 'd4-entrevista', topic: 'Entrevista', sub: 'Comunicación', difficulty: 1,
    q: '¿Qué es el método STAR técnico?',
    a: 'Situación, Tarea, Acción y Resultado. En versión técnica, la acción incluye comandos y decisiones, y el resultado es medible. Mantiene la respuesta en 60-90 segundos y demuestra método.',
    example: 'S: 502 en producción. T: restaurar servicio. A: revisé error log, endpoints y targetPort; apliqué rollback. R: 0 errores en 5 min.',
    misconceptions: ['Narrar sin resultado', 'Extenderse sin estructura'],
    related: ['c-tradeoff', 'c-no-se'], tags: ['entrevista'] },
  { id: 'c-tradeoff', module: 'd4-entrevista', topic: 'Entrevista', sub: 'Comunicación', difficulty: 2,
    q: '¿Cómo se responde una pregunta de tradeoff?',
    a: 'Elegir una opción, justificar con el contexto (equipo, escala, criticidad), reconocer el costo de esa elección y decir cuándo cambiarías. No existe la opción correcta universal.',
    example: 'VM vs contenedor: "contenedor por densidad y velocidad de deploy; pierdo aislamiento fuerte, aceptable para esta app stateless".',
    misconceptions: ['Dar una sola respuesta sin contexto', 'Decir que una opción es siempre mejor'],
    related: ['c-star', 'c-no-se'], tags: ['entrevista'] },
  { id: 'c-no-se', module: 'd4-entrevista', topic: 'Entrevista', sub: 'Comunicación', difficulty: 2,
    q: '¿Qué responder si no sabés algo en una entrevista técnica?',
    a: 'Decirlo con honestidad, explicar cómo lo averiguarías (documentación, plan de prueba, comando de verificación) y conectar con un concepto cercano que sí domines. Inventar es lo que más resta.',
    example: '"No lo usé en producción; entiendo que se resuelve con X, lo verificaría leyendo la doc y probando en un entorno aislado."',
    misconceptions: ['Inventar una respuesta', 'Quedarse en "no sé" sin proponer cómo averiguarlo'],
    related: ['c-star', 'c-tradeoff'], tags: ['entrevista'] },
  { id: 'c-preguntas', module: 'd4-entrevista', topic: 'Entrevista', sub: 'Comunicación', difficulty: 1,
    q: '¿Qué preguntas conviene hacer al entrevistador?',
    a: 'Sobre el trabajo real: cómo es el pipeline, qué incidentes tuvieron el último mes, cómo se decide un deploy, qué parte del stack duele más y cómo se mide el éxito del rol. Demuestran interés y criterio.',
    example: '"¿Cómo es el flujo desde el commit hasta producción? ¿Qué incidentes tuvieron el último mes?"',
    misconceptions: ['No hacer preguntas', 'Preguntar solo por beneficios'],
    related: ['c-star', 'c-tradeoff'], tags: ['entrevista'] },

  /* ---------- Ampliación LPI 701-200 ---------- */
  { id: 'c-lfcs-storage-1', module: 'lfcs-storage', topic: 'Linux', sub: 'Almacenamiento', difficulty: 2,
    q: '¿Por qué se usa UUID en /etc/fstab en lugar de /dev/sdb1?',
    a: 'Porque el nombre del dispositivo puede cambiar según el orden de detección o la controladora. El UUID identifica el filesystem de forma estable. Se obtiene con blkid o lsblk -f y se escribe como UUID=....',
    example: 'UUID=5f2c9a1e-... /srv/datos ext4 defaults,nofail 0 2',
    misconceptions: ['Creer que sda siempre es el mismo disco', 'Usar LABEL sin controlar duplicados'],
    related: ['c-lfcs-storage-2', 'c-fhs-etc'], tags: ['linux', 'storage'] },
  { id: 'c-lfcs-storage-2', module: 'lfcs-storage', topic: 'Linux', sub: 'LVM', difficulty: 3,
    q: '¿Qué son PV, VG y LV y cómo se extiende un volumen lógico?',
    a: 'PV es el disco o partición física; VG agrupa PVs en un pool; LV es el volumen lógico que se formatea y monta. Se extiende con lvextend -r -L +5G /dev/vg0/datos si el VG tiene espacio libre; -r redimensiona también el filesystem.',
    example: 'pvs; vgs; lvs\nsudo lvextend -r -L +5G /dev/vg0/datos\ndf -h /srv/datos',
    misconceptions: ['Extender el LV sin redimensionar el filesystem', 'Confundir VG con un filesystem'],
    related: ['c-lfcs-storage-1'], tags: ['linux', 'storage', 'lvm'] },
  { id: 'c-lfcs-systemd-1', module: 'lfcs-systemd', topic: 'Linux', sub: 'systemd', difficulty: 2,
    q: '¿Qué diferencia hay entre un .service y un .timer, y cuál se habilita?',
    a: 'El .service define el proceso (ExecStart) y el .timer define cuándo se dispara (OnCalendar). Se habilita el timer con systemctl enable --now backup.timer; el service se ejecuta cuando el timer dispara. Persistent=true recupera ejecuciones perdidas si el equipo estaba apagado.',
    example: '[Timer]\nOnCalendar=*-*-* 03:00:00\nPersistent=true\n[Install]\nWantedBy=timers.target',
    misconceptions: ['Habilitar el service y esperar que se ejecute solo', 'Confundir OnCalendar con un cron sin zona horaria'],
    related: ['c-lfcs-systemd-2', 'c-systemd-enable'], tags: ['linux', 'systemd'] },
  { id: 'c-lfcs-systemd-2', module: 'lfcs-systemd', topic: 'Linux', sub: 'systemd', difficulty: 2,
    q: '¿Cómo hacés persistentes los logs de journald entre reinicios?',
    a: 'journald escribe en /run/log/journal (volátil) por defecto. Para persistir: crear /var/log/journal y configurar Storage=persistent en /etc/systemd/journald.conf, luego reiniciar systemd-journald. journalctl -b -1 solo funciona si el arranque anterior quedó guardado.',
    example: 'sudo mkdir -p /var/log/journal\nsudo systemctl restart systemd-journald\njournalctl -b -1 -p err',
    misconceptions: ['Asumir que el journal siempre persiste', 'Buscar logs viejos en /var/log aunque journald sea volátil'],
    related: ['c-lfcs-systemd-1', 'c-journalctl'], tags: ['linux', 'systemd', 'logs'] },
  { id: 'c-lpi701-arq-1', module: 'lpi701-arq', topic: 'Diseño', sub: 'APIs', difficulty: 2,
    q: '¿Qué significa que PUT y DELETE sean idempotentes y por qué importa en reintentos?',
    a: 'Repetir la misma llamada con el mismo payload deja el sistema en el mismo estado: PUT reemplaza el recurso y DELETE lo elimina. Importa porque clientes, proxies y colas reintentan ante timeout; sin idempotencia, un reintento puede duplicar un cobro o crear dos pedidos.',
    example: 'PUT /v1/orders/42 (mismo body) → mismo resultado\nPOST /v1/payments + Idempotency-Key → una sola transacción',
    misconceptions: ['Decir que POST es idempotente', 'Confundir idempotencia con ausencia de efectos'],
    related: ['c-lpi701-arq-2'], tags: ['diseño', 'api'] },
  { id: 'c-lpi701-arq-2', module: 'lpi701-arq', topic: 'Diseño', sub: 'Estado', difficulty: 2,
    q: '¿Dónde debe vivir la sesión si la app corre en varias réplicas?',
    a: 'Fuera del proceso: en un almacén compartido (Redis, base de datos) o en un token firmado como JWT. Si vive en la memoria del proceso, el balanceador manda al usuario a otra réplica y la sesión se pierde. JWT evita el almacén pero no permite revocar sin lista negra.',
    example: 'Redis: SET session:42 <id> EX 1800\nJWT: firma + expiración corta + refresh token',
    misconceptions: ['Guardar sesión en memoria y escalar', 'Usar JWT como única solución sin revocación'],
    related: ['c-lpi701-arq-1'], tags: ['diseño', 'sesión'] },
  { id: 'c-lpi701-plataformas-1', module: 'lpi701-plataformas', topic: 'Cloud', sub: 'Almacenamiento', difficulty: 2,
    q: '¿Cuándo usás almacenamiento de objetos y cuándo un volumen de bloque?',
    a: 'Objetos (S3/GCS/Blob) para archivos completos, backups, estáticos y acceso por HTTP; se escalan solos pero no ofrecen locking ni append POSIX. Bloque (EBS) para el disco de una VM donde corre un filesystem o una base de datos que necesita baja latencia y escritura a nivel de bloque.',
    example: 'Imágenes → S3 + URL prefirmada\nDatos de PostgreSQL → volumen EBS formateado ext4',
    misconceptions: ['Montar un bucket como disco de base de datos', 'Guardar backups solo en el disco de la VM'],
    related: ['c-lpi701-plataformas-2', 'c-var'], tags: ['cloud', 'storage'] },
  { id: 'c-lpi701-plataformas-2', module: 'lpi701-plataformas', topic: 'Cloud', sub: 'Mensajería', difficulty: 3,
    q: '¿Qué implica una entrega at-least-once y qué debe hacer el consumidor?',
    a: 'El broker garantiza que el mensaje no se pierda, pero puede entregarlo más de una vez. El consumidor debe ser idempotente (por ID de mensaje o clave de negocio) y el sistema necesita una dead-letter queue para los mensajes que fallan repetidamente.',
    example: 'Kafka consumer group: offset commit después del procesamiento\nif (!yaProcesado(msg.id)) procesar(msg.id)',
    misconceptions: ['Asumir exactly-once sin diseñarlo', 'Descartar duplicados sin clave de idempotencia'],
    related: ['c-lpi701-plataformas-1'], tags: ['cloud', 'broker'] },
  { id: 'c-lpi701-licencias-1', module: 'lpi701-licencias', topic: 'DevSecOps', sub: 'Licencias', difficulty: 2,
    q: '¿Cuál es la diferencia entre una licencia permisiva y una copyleft?',
    a: 'La permisiva (MIT, BSD, Apache 2.0) permite usar y distribuir en software propietario conservando avisos. La copyleft (GPL, LGPL, AGPL) obliga a liberar el código derivado bajo la misma licencia al distribuir; AGPL extiende la obligación al uso como servicio por red.',
    example: 'MIT: aviso de copyright\nGPL: entregar el fuente del binario distribuido\nAGPL: ofrecer el fuente a los usuarios del SaaS',
    misconceptions: ['Decir que open source es libre de toda obligación', 'Creer que AGPL solo aplica si distribuís el binario'],
    related: ['c-lpi701-licencias-2'], tags: ['licencias', 'open source'] },
  { id: 'c-lpi701-licencias-2', module: 'lpi701-licencias', topic: 'DevSecOps', sub: 'SBOM', difficulty: 2,
    q: '¿Qué es un SBOM y para qué sirve en una entrega?',
    a: 'Un Software Bill of Materials lista componentes, versiones y licencias en un formato estándar (SPDX o CycloneDX). Permite responder rápido qué dependencias incluye un artefacto, detectar vulnerabilidades y auditar licencias en una due diligence o incidente de supply chain.',
    example: 'syft dir:. -o spdx-json > sbom.json\ngrype sbom:sbom.json',
    misconceptions: ['Confundir SBOM con un escaneo de vulnerabilidades', 'Generarlo una vez y no adjuntarlo al artefacto'],
    related: ['c-lpi701-licencias-1'], tags: ['licencias', 'sbom'] },
  { id: 'c-lpi703-helm-1', module: 'lpi703-helm', topic: 'Kubernetes', sub: 'Helm', difficulty: 2,
    q: '¿Qué es un chart, un release y un values.yaml?',
    a: 'El chart es el paquete de plantillas y metadatos; el release es una instalación con nombre y namespace; values.yaml aporta los valores por defecto que se sobrescriben por entorno. Cada upgrade crea una revisión que helm rollback puede restaurar.',
    example: 'helm install web bitnami/nginx -f values-prod.yaml -n prod\nhelm history web -n prod',
    misconceptions: ['Confundir chart con release', 'Guardar secretos en values.yaml del repositorio'],
    related: ['c-lpi703-helm-2', 'c-k8s-deploy'], tags: ['k8s', 'helm'] },
  { id: 'c-lpi703-helm-2', module: 'lpi703-helm', topic: 'Kubernetes', sub: 'GitOps', difficulty: 3,
    q: '¿Cuándo elegís Helm y cuándo Kustomize?',
    a: 'Helm para empaquetar y distribuir software de terceros o parametrizar charts complejos; Kustomize para superponer variaciones de entorno sobre manifiestos propios sin plantillas. Argo CD o Flux aplican GitOps: el estado deseado vive en Git y el clúster se reconcilia; el rollback es un revert del commit.',
    example: 'helm template app ./chart -f values-prod.yaml\nkubectl apply -k overlays/prod\nargocd app sync api',
    misconceptions: ['Usar Helm para todo aunque el YAML sea propio y simple', 'Editar a mano recursos gestionados por GitOps'],
    related: ['c-lpi703-helm-1'], tags: ['k8s', 'gitops'] },
  { id: 'c-lpi704-logs-1', module: 'lpi704-logs', topic: 'Observabilidad', sub: 'Logs', difficulty: 2,
    q: '¿Cuándo conviene Loki y cuándo Elasticsearch para logs?',
    a: 'Loki indexa solo labels y guarda el contenido comprimido: es barato y rápido si consultás por servicio, namespace y rango de tiempo. Elasticsearch/OpenSearch indexa el texto completo: permite búsquedas complejas y agregaciones, a costo de almacenamiento y operación mucho mayores.',
    example: 'Loki: {app="api", namespace="prod"} |= "error"\nElasticsearch: full-text y aggregations por campo',
    misconceptions: ['Usar user_id como label en Loki y explotar la cardinalidad', 'Elegir Elasticsearch por defecto sin presupuesto'],
    related: ['c-lpi704-logs-2', 'c-logs'], tags: ['observabilidad', 'logs'] },
  { id: 'c-lpi704-logs-2', module: 'lpi704-logs', topic: 'Observabilidad', sub: 'Logs', difficulty: 2,
    q: '¿Qué campos mínimos debería tener un log estructurado y qué nunca debería incluir?',
    a: 'timestamp, level, service, environment, trace_id/request_id y un mensaje con contexto. Nunca credenciales, tokens, números de tarjeta ni datos personales completos; se seudonimizan o se excluyen. El formato JSON permite filtrar y correlacionar sin regex frágiles.',
    example: '{"ts":"...","level":"error","service":"api","trace_id":"4bf9...","msg":"payment failed","order_id":42}',
    misconceptions: ['Loguear el body completo de la request', 'Usar logs sin estructura y depender de grep'],
    related: ['c-lpi704-logs-1'], tags: ['observabilidad', 'logs', 'seguridad'] },
  { id: 'c-lpi704-tracing-1', module: 'lpi704-tracing', topic: 'Observabilidad', sub: 'Tracing', difficulty: 3,
    q: '¿Qué es un span y cómo se relaciona con un trace?',
    a: 'Un span es una unidad de trabajo con nombre, inicio, duración, atributos y estado; un trace es el árbol de spans de una request completa, unidos por trace_id y relaciones padre-hijo. El span raíz representa la request y los hijos, las llamadas a servicios, base o cola.',
    example: 'trace_id: 4bf9...\n├─ gateway GET /orders 12ms\n│  └─ api query orders 180ms\n│     └─ db SELECT 150ms',
    misconceptions: ['Confundir trace con métrica', 'Generar un trace_id nuevo en cada servicio'],
    related: ['c-lpi704-tracing-2'], tags: ['observabilidad', 'tracing'] },
  { id: 'c-lpi704-tracing-2', module: 'lpi704-tracing', topic: 'Observabilidad', sub: 'Muestreo', difficulty: 3,
    q: '¿Qué diferencia hay entre head sampling y tail sampling?',
    a: 'Head sampling decide al inicio de la traza (simple y barato, pero puede descartar justo las trazas lentas o con error). Tail sampling decide en el Collector al final, cuando ya vio la duración y el estado: permite conservar 100% de errores y latencias altas pagando un buffer en memoria.',
    example: 'OTel Collector tail_sampling:\n- latency > 500ms\n- status_code = ERROR\n- probabilistic 10%',
    misconceptions: ['Muestrear 100% en producción sin costo', 'Creer que head sampling conserva los errores'],
    related: ['c-lpi704-tracing-1'], tags: ['observabilidad', 'tracing', 'costo'] },
  { id: 'c-tf-equipo-1', module: 'tf-equipo', topic: 'Terraform', sub: 'State', difficulty: 3,
    q: '¿Por qué el state de Terraform va en un backend remoto con lock?',
    a: 'Porque el state mapea recursos declarados con IDs reales y es la fuente de verdad. El backend remoto lo comparte el equipo, lo versiona y lo cifra; el lock impide que dos applies simultáneos lean el mismo state y uno pise al otro. Nunca se commitea a Git.',
    example: 'terraform {\n  backend "s3" {\n    bucket = "empresa-tfstate"\n    key = "prod/terraform.tfstate"\n    dynamodb_table = "tf-lock"\n  }\n}',
    misconceptions: ['Compartir el state por chat', 'Commitear tfstate porque es solo texto'],
    related: ['c-tf-equipo-2', 'c-terraform-state'], tags: ['terraform', 'state'] },
  { id: 'c-tf-equipo-2', module: 'tf-equipo', topic: 'Terraform', sub: 'Operación', difficulty: 3,
    q: '¿Qué es el drift y cómo lo detectás y corregís?',
    a: 'Drift es la diferencia entre el state y la realidad, normalmente por cambios manuales en la consola o por otro proceso. Se detecta con un plan periódico (plan -detailed-exitcode devuelve 2 si hay cambios) y se corrige aplicando el estado deseado, importando el recurso existente o moviéndolo con un bloque moved.',
    example: 'terraform plan -detailed-exitcode; echo $?\nterraform import aws_instance.web i-0abc123',
    misconceptions: ['Arreglar el drift borrando el state', 'Recrear recursos en lugar de importarlos'],
    related: ['c-tf-equipo-1'], tags: ['terraform', 'drift'] },
  { id: 'c-git-submodulo', module: 'd1-git', topic: 'Git', sub: 'Repositorios', difficulty: 3,
    q: '¿Qué es un submódulo y en qué se diferencia un SCM centralizado de uno distribuido?',
    a: 'Un submódulo referencia otro repositorio en un commit fijo y hay que inicializarlo con git submodule update --init --recursive. Git es distribuido: cada clon tiene la historia completa y puede commitear sin red. SVN y CVS son centralizados: el servidor guarda la historia y el cliente solo una copia de trabajo.',
    example: 'git submodule add https://git.local/lib.git libs/lib\ngit submodule update --init --recursive',
    misconceptions: ['Creer que el submódulo sigue automáticamente la última versión', 'Confundir distribuido con ausencia de servidor remoto'],
    related: ['c-git-areas'], tags: ['git', 'scm'] },
  { id: 'c-podman', module: 'd2-contenedores', topic: 'Docker', sub: 'Runtime', difficulty: 2,
    q: '¿Qué ventaja ofrece Podman frente a Docker y qué es un contenedor rootless?',
    a: 'Podman es daemonless: no necesita un daemon root corriendo y puede ejecutar contenedores rootless usando user namespaces, lo que reduce el impacto de una fuga. Las imágenes son OCI, así que la misma imagen corre en Docker, Podman y Kubernetes. La sintaxis es casi idéntica.',
    example: 'podman run -d -p 8080:80 nginx:1.27\npodman pod ps',
    misconceptions: ['Creer que Podman usa imágenes distintas', 'Pensar que rootless elimina todo riesgo de escape'],
    related: ['c-docker-vm'], tags: ['docker', 'podman'] },
  { id: 'c-k8s-storage', module: 'd3-k8s-workloads', topic: 'Kubernetes', sub: 'Storage', difficulty: 3,
    q: '¿Cómo usa un Pod un PersistentVolumeClaim?',
    a: 'El PVC declara accessModes y tamaño; se vincula a un PV compatible o a una StorageClass con aprovisionamiento dinámico. El Pod declara un volume con persistentVolumeClaim.claimName y lo monta en el contenedor. ReadWriteOnce es un solo nodo; ReadWriteMany requiere un backend que lo soporte.',
    example: 'volumes:\n  - name: datos\n    persistentVolumeClaim:\n      claimName: datos-api',
    misconceptions: ['Montar el PVC sin declarar el volume en el Pod', 'Asumir ReadWriteMany con cualquier StorageClass'],
    related: ['c-k8s-deploy'], tags: ['k8s', 'storage'] },
  { id: 'c-k8s-workload-kinds', module: 'd3-k8s-workloads', topic: 'Kubernetes', sub: 'Workloads', difficulty: 3,
    q: '¿Cuándo usás StatefulSet, DaemonSet, Job o CronJob?',
    a: 'StatefulSet para identidad y almacenamiento estable por réplica (bases de datos); DaemonSet para exactamente un Pod por nodo (agentes de logs o métricas); Job para una tarea que termina; CronJob para ejecuciones programadas. Deployment es para servicios sin estado que se pueden reemplazar en cualquier nodo.',
    example: 'StatefulSet: postgres-0, postgres-1 con PVC propio\nDaemonSet: fluent-bit en cada nodo',
    misconceptions: ['Usar Deployment para una base de datos con disco', 'Usar un CronJob para un servicio permanente'],
    related: ['c-k8s-storage'], tags: ['k8s', 'workloads'] },
  { id: 'c-oidc', module: 'd4-devsecops', topic: 'DevSecOps', sub: 'Identidad', difficulty: 3,
    q: '¿Qué diferencia hay entre OAuth2, OpenID Connect y SAML?',
    a: 'OAuth2 es un marco de autorización delegada (acceso a recursos); OpenID Connect agrega una capa de identidad sobre OAuth2 con un ID token y userinfo; SAML es un estándar XML de federación de identidad muy usado en empresas. Para 2FA se usa TOTP con una app autenticadora; las contraseñas se almacenan con hash + salt.',
    example: 'Flujo OIDC: authorization code + PKCE → ID token → userinfo\nTOTP: código de 6 dígitos cada 30 s',
    misconceptions: ['Decir que OAuth2 autentica por sí solo', 'Guardar contraseñas cifradas de forma reversible'],
    related: ['c-suid'], tags: ['seguridad', 'identidad'] },
  { id: 'c-prom-exporters', module: 'd4-observabilidad', topic: 'Observabilidad', sub: 'Prometheus', difficulty: 2,
    q: '¿Para qué sirven node_exporter, blackbox_exporter y Thanos?',
    a: 'node_exporter expone métricas del host (CPU, memoria, disco, red); blackbox_exporter sondea endpoints HTTP/TCP/ICMP desde afuera y devuelve éxito y latencia; Thanos agrega retención larga y consultas globales sobre varios Prometheus, porque el Prometheus local no es un archivo histórico.',
    example: 'scrape_configs:\n  - job_name: node\n    static_configs: [{ targets: ["host:9100"] }]',
    misconceptions: ['Usar Prometheus local como archivo de meses', 'Monitorear solo CPU y no la disponibilidad del endpoint'],
    related: ['c-promql'], tags: ['observabilidad', 'prometheus'] }
];
